window.COURSE=[{"id": 1, "title": "Tu primer análisis", "short": "Primeros pasos", "phase": "Badge 1 · Fundamentos de Python", "description": "Convierte una pregunta cotidiana en variables, cálculos y una respuesta.", "objectives": ["Ejecutar un notebook en orden.", "Distinguir texto, números y booleanos.", "Calcular e interpretar un ingreso."], "lessons": [{"title": "Una pregunta antes del código", "text": ["Una librería vende cuatro cuadernos a ₡1500 cada uno. Define primero la pregunta: ¿cuál es el ingreso de esa venta? El precio es un monto por unidad y la cantidad es un número de unidades. Su producto es un monto total.", "En un notebook conviven celdas de texto y código. Ejecuta con Shift + Enter. Python conserva variables mientras la sesión está activa: una celda que usa precio necesita que antes se haya ejecutado su asignación."], "code": "precio = 1500\ncantidad = 4\ningreso = precio * cantidad\nprint(\"Ingreso:\", ingreso)", "output": "Ingreso: 6000", "tip": "₡6000 es ingreso por ventas. No es ganancia: todavía no has descontado costos."}, {"title": "Un nombre para cada dato", "text": ["Una variable asocia un nombre con un valor. Usa nombres como precio_unitario en lugar de letras ambiguas. Python distingue mayúsculas: Precio y precio son nombres diferentes.", "str representa texto; int, enteros; float, decimales; bool, verdadero o falso. El signo = asigna un valor. El operador == compara dos valores."], "code": "producto = \"Cuaderno\"\ncantidad = 4\nprecio = 1500.0\nhay_stock = cantidad > 0\nprint(type(producto).__name__)\nprint(type(cantidad).__name__)\nprint(type(precio).__name__)\nprint(hay_stock)", "output": "str, int, float y True, en líneas separadas.", "tip": "Escribe texto entre comillas. True y False se escriben con inicial mayúscula y sin comillas."}, {"title": "Convertir, calcular y comprobar", "text": ["Los datos pueden llegar como texto. float(\"1500.50\") convierte un texto numérico a decimal; int(\"4\") lo convierte a entero. Una conversión falla si el texto no representa el tipo esperado.", "Lee un mensaje de error desde su última línea: suele indicar el tipo y la causa. Reiniciar y ejecutar todo permite detectar dependencias ocultas entre celdas."], "code": "precio_texto = \"1500.50\"\ncantidad_texto = \"4\"\ntotal = float(precio_texto) * int(cantidad_texto)\nprint(round(total, 2))\nprint(total > 5000)", "output": "6002.0 y True.", "tip": "Los decimales binarios pueden ser aproximados. Redondear al mostrar es útil; los cálculos financieros exactos requieren decisiones adicionales."}], "tasks": [{"title": "Una compra pequeña", "prompt": "Calcula el ingreso de 6 lapiceros a ₡500. Imprime el monto y una etiqueta que indique su significado.", "check": "El resultado es ₡3000.", "hint": "Usa dos variables y una multiplicación.", "solution": "precio = 500\ncantidad = 6\nprint(\"Ingreso en colones:\", precio * cantidad)", "explanation": "El precio se expresa por unidad; multiplicarlo por seis da el ingreso total."}, {"title": "Texto que representa números", "prompt": "Convierte \"800\" y \"5\" en números. Calcula el ingreso e indica si supera ₡3500.", "check": "4000 y True.", "hint": "Usa int y el operador >.", "solution": "precio = int(\"800\")\ncantidad = int(\"5\")\ningreso = precio * cantidad\nprint(ingreso)\nprint(ingreso > 3500)", "explanation": "Comparar produce un booleano; no cambia el ingreso."}], "quiz": [{"question": "¿Qué hace precio = 1500?", "options": ["Compara dos cantidades", "Asigna un valor a un nombre", "Imprime 1500"], "answer": 1, "explanation": "= asigna. Para comparar igualdad usamos ==."}, {"question": "¿Qué produce float(\"1500.50\")?", "options": ["Un número decimal", "Una lista", "El texto sin cambios"], "answer": 0, "explanation": "float convierte un texto numérico válido en un número decimal."}, {"question": "¿Por qué reiniciar y ejecutar todo?", "options": ["Para comprobar que el notebook funciona en orden", "Para cambiar los datos originales", "Para borrar todos los archivos"], "answer": 0, "explanation": "La ejecución completa revela variables que dependían de celdas ejecutadas fuera de orden."}], "homework": {"title": "Tu primera factura", "context": "Una compra incluye 3 cuadernos a ₡1500 y 2 reglas a ₡600.", "steps": ["Crea variables con nombres claros para cada precio y cantidad.", "Calcula el ingreso de cada producto y el total.", "Comprueba si el total supera ₡5000.", "Explica la diferencia entre ingreso y ganancia. Control: total ₡5700."]}, "badge": 1}, {"id": 2, "title": "Organiza tus datos", "short": "Listas y diccionarios", "phase": "Badge 1 · Fundamentos de Python", "description": "Pasa de valores aislados a colecciones que representan productos y registros.", "objectives": ["Acceder a elementos por posición o clave.", "Usar listas y diccionarios.", "Reconocer tuplas y conjuntos."], "lessons": [{"title": "Listas: una secuencia con orden", "text": ["Una lista reúne valores en un orden. Los índices comienzan en cero y -1 selecciona el último elemento. len informa cuántos elementos contiene.", "El rango [inicio:fin] incluye el inicio y excluye el final. append agrega un elemento al final y modifica la lista existente."], "code": "productos = [\"Cuaderno\", \"Lapicero\", \"Regla\"]\nprint(productos[0])\nprint(productos[-1])\nprint(productos[0:2])\nproductos.append(\"Carpeta\")\nprint(len(productos))", "output": "Cuaderno; Regla; [Cuaderno, Lapicero]; 4.", "tip": "No confundas cantidad de elementos con última posición: una lista de cuatro elementos termina en la posición 3."}, {"title": "Diccionarios: un registro con nombres", "text": ["Un diccionario relaciona claves con valores. Es una buena forma de representar un registro: Producto, Precio y Cantidad explican qué significa cada valor.", "Acceder a una clave inexistente con corchetes produce KeyError. get permite expresar un valor por defecto cuando la ausencia es esperable. No ocultes errores tipográficos con valores por defecto."], "code": "venta = {\"Producto\": \"Cuaderno\", \"Precio\": 1500, \"Cantidad\": 4}\nprint(venta[\"Producto\"])\nventa[\"Ingreso\"] = venta[\"Precio\"] * venta[\"Cantidad\"]\nprint(venta[\"Ingreso\"])\nprint(venta.get(\"Descuento\", 0))", "output": "Cuaderno; 6000; 0.", "tip": "Las claves son nombres; las posiciones son números que describen un lugar. Son dos formas distintas de acceder a datos."}, {"title": "Elegir la colección adecuada", "text": ["Una lista de diccionarios puede representar varias ventas. Una tupla agrupa valores que no se modifican mediante asignación de elementos. Un conjunto guarda elementos únicos y no ofrece acceso por posición.", "Convertir una lista en conjunto sirve para reconocer categorías únicas. No utilices el orden de un conjunto para organizar una entrega; ordénalo explícitamente si lo necesitas."], "code": "ventas = [{\"Producto\": \"Mouse\", \"Cantidad\": 3},\n          {\"Producto\": \"Teclado\", \"Cantidad\": 2}]\nprint(ventas[1][\"Producto\"])\ncoordenada = (10, 20)\nprint(coordenada[0])\nciudades = [\"San José\", \"Cartago\", \"San José\"]\nprint(sorted(set(ciudades)))", "output": "Teclado; 10; [Cartago, San José].", "tip": "Eliminar repeticiones no siempre es limpiar: dos ventas iguales pueden ser eventos válidos distintos."}], "tasks": [{"title": "Selecciona sin adivinar", "prompt": "De la lista [100, 130, 119, 92, 35], muestra el segundo valor, el último y los primeros tres.", "check": "130; 35; [100, 130, 119].", "hint": "Usa [1], [-1] y [:3].", "solution": "ventas = [100, 130, 119, 92, 35]\nprint(ventas[1])\nprint(ventas[-1])\nprint(ventas[:3])", "explanation": "El límite superior del rango no se incluye."}, {"title": "Describe una venta", "prompt": "Construye un diccionario para 3 carpetas a ₡1200 e incorpora su ingreso.", "check": "Ingreso 3600.", "hint": "Asigna una nueva clave Ingreso.", "solution": "venta = {\"Producto\": \"Carpeta\", \"Precio\": 1200, \"Cantidad\": 3}\nventa[\"Ingreso\"] = venta[\"Precio\"] * venta[\"Cantidad\"]\nprint(venta)", "explanation": "El diccionario conserva juntos los atributos del mismo registro."}], "quiz": [{"question": "¿Qué selecciona lista[1]?", "options": ["El primer elemento", "El segundo elemento", "El último elemento"], "answer": 1, "explanation": "El índice 0 es la primera posición; 1 es la segunda."}, {"question": "¿Qué estructura relaciona nombres con valores?", "options": ["Diccionario", "Conjunto", "Decimal"], "answer": 0, "explanation": "Un diccionario representa pares clave–valor."}, {"question": "¿Qué conserva set([1, 1, 2])?", "options": ["Tres elementos ordenados", "Los valores únicos 1 y 2", "Solo el 1"], "answer": 1, "explanation": "El conjunto conserva valores únicos y no garantiza un orden de presentación."}], "homework": {"title": "Un pequeño inventario", "context": "Representa Cuaderno (₡1500, 4 unidades), Regla (₡600, 2) y Carpeta (₡1200, 3).", "steps": ["Crea una lista con tres diccionarios.", "Consulta el nombre del segundo producto.", "Calcula manualmente el ingreso del tercer registro usando sus claves.", "Explica por qué una lista de nombres no basta para guardar precios y cantidades."]}, "badge": 1}, {"id": 3, "title": "Haz que tu código decida", "short": "Lógica y funciones", "phase": "Badge 1 · Fundamentos de Python", "description": "Automatiza decisiones sencillas y reutiliza cálculos con funciones pequeñas.", "objectives": ["Construir una condición.", "Recorrer una lista.", "Crear una función con return."], "lessons": [{"title": "Condiciones: una regla explícita", "text": ["if ejecuta un bloque cuando una condición es verdadera. elif permite probar otra condición y else cubre el caso restante. La indentación define qué instrucciones pertenecen a cada bloque.", "Una regla debe ser precisa: cantidad >= 5 incluye el cinco; cantidad > 5 no lo incluye. Antes de programar, escribe qué debe pasar en el límite."], "code": "cantidad = 5\nif cantidad >= 5:\n    descuento = 0.10\nelse:\n    descuento = 0.0\nprint(\"Descuento:\", descuento)", "output": "Descuento: 0.1.", "tip": "Prueba valores debajo, en y encima del límite: 4, 5 y 6."}, {"title": "Ciclos: repetir una operación", "text": ["for recorre los elementos de una colección. Un acumulador comienza con un valor inicial y se actualiza en cada repetición.", "Un ciclo ayuda a comprender el proceso. Más adelante usarás operaciones de Pandas para calcular columnas completas."], "code": "cantidades = [4, 10, 3]\ntotal = 0\nfor cantidad in cantidades:\n    total = total + cantidad\nprint(\"Unidades:\", total)\nprint(\"Comprobación:\", sum(cantidades))", "output": "Ambos resultados son 17.", "tip": "Inicializa el acumulador antes del ciclo. Si lo reinicias dentro, pierdes lo acumulado."}, {"title": "Funciones: entradas, resultado y responsabilidad", "text": ["def define una función. Los parámetros nombran sus entradas. return entrega un resultado que puede usarse en otros cálculos; print solo muestra información.", "Una función pequeña debe tener una tarea clara. Aquí calculamos un ingreso con descuento. El descuento se expresa como proporción: 0.10 equivale a 10 %."], "code": "def calcular_ingreso(precio, cantidad, descuento=0):\n    return precio * cantidad * (1 - descuento)\n\nnormal = calcular_ingreso(1500, 4)\nrebajado = calcular_ingreso(1500, 4, 0.10)\nprint(normal, rebajado)", "output": "6000 y 5400.0.", "tip": "Evita depender de variables externas si puedes pasarlas como parámetros: la función será más fácil de revisar."}], "tasks": [{"title": "Clasificar cantidades", "prompt": "Recorre [2, 5, 8] e imprime \"mayorista\" para cantidades >= 5 y \"regular\" para el resto.", "check": "regular, mayorista, mayorista.", "hint": "Combina for con if.", "solution": "for cantidad in [2, 5, 8]:\n    if cantidad >= 5:\n        print(\"mayorista\")\n    else:\n        print(\"regular\")", "explanation": "El valor 5 pertenece al grupo mayorista porque la condición incluye igualdad."}, {"title": "Reutilizar un cálculo", "prompt": "Define una función total(precio, cantidad). Calcula dos compras: 500 × 6 y 1200 × 3.", "check": "3000 y 3600.", "hint": "Usa return para devolver el producto.", "solution": "def total(precio, cantidad):\n    return precio * cantidad\n\nprint(total(500, 6))\nprint(total(1200, 3))", "explanation": "Los argumentos cambian, pero la regla de cálculo se escribe una sola vez."}], "quiz": [{"question": "¿Qué instrucción devuelve un valor desde una función?", "options": ["print", "return", "for"], "answer": 1, "explanation": "return permite que quien llama la función utilice su resultado."}, {"question": "¿Qué ocurre con cantidad = 5 y cantidad >= 5?", "options": ["La condición es verdadera", "La condición es falsa", "Siempre produce error"], "answer": 0, "explanation": ">= incluye el valor límite."}, {"question": "¿Dónde se inicia un acumulador?", "options": ["Dentro de cada repetición", "Antes del ciclo", "Solo al imprimir"], "answer": 1, "explanation": "Inicializarlo antes evita borrar el total parcial en cada iteración."}], "homework": {"title": "Descuentos con reglas", "context": "Una tienda aplica 10 % de descuento cuando una compra incluye al menos 5 unidades.", "steps": ["Define una función que calcule el total con esa regla.", "Evalúa cantidades 4, 5 y 6 con precio ₡1000.", "Guarda los resultados en una lista usando un ciclo.", "Explica los resultados de control: ₡4000, ₡4500 y ₡5400."]}, "badge": 1}, {"id": 4, "title": "Trabaja con confianza", "short": "Archivos y errores", "phase": "Badge 1 · Fundamentos de Python", "description": "Aprende a ubicar tus archivos, entender los errores y entregar un trabajo reproducible.", "objectives": ["Interpretar errores comunes.", "Leer y escribir un CSV sencillo.", "Preparar un notebook reproducible."], "lessons": [{"title": "Rutas y archivos de datos", "text": ["Una ruta relativa se interpreta desde la carpeta de trabajo, que no siempre coincide con la ubicación que imaginas. Path.cwd() permite consultarla.", "El paquete contiene las carpetas datos y notebooks. Los ejemplos de lectura de CSV preparan la ruta DATOS buscando los archivos en datos, ../datos o la carpeta actual. En Colab, sube los CSV al panel Archivos."], "code": "from pathlib import Path\n\ncarpeta = Path.cwd()\nprint(\"Carpeta de trabajo:\", carpeta.name)\narchivo = Path(\"datos\") / \"ventas.csv\"\nprint(\"Ruta relativa:\", archivo.as_posix())", "output": "El nombre de la carpeta depende de tu entorno; la ruta relativa mostrada es datos/ventas.csv.", "tip": "No copies rutas personales de otra computadora. Usa la estructura del paquete y documenta dónde están los datos."}, {"title": "CSV: texto organizado en columnas", "text": ["Un CSV guarda registros en texto separados por un delimitador. Aquí usamos comas. DictReader interpreta la primera fila como nombres de columnas; los valores leídos son texto.", "Este ejemplo crea un archivo pequeño de práctica. utf-8 permite guardar acentos. newline=\"\" evita problemas con saltos de línea al escribir CSV."], "code": "import csv\nfrom pathlib import Path\n\nruta = Path(\"compra_practica.csv\")\nwith ruta.open(\"w\", encoding=\"utf-8\", newline=\"\") as archivo:\n    escritor = csv.DictWriter(archivo, fieldnames=[\"Producto\", \"Cantidad\"])\n    escritor.writeheader()\n    escritor.writerow({\"Producto\": \"Cuaderno\", \"Cantidad\": 4})\n\nwith ruta.open(encoding=\"utf-8\", newline=\"\") as archivo:\n    filas = list(csv.DictReader(archivo))\nprint(filas[0][\"Producto\"])\nprint(int(filas[0][\"Cantidad\"]))", "output": "Cuaderno y 4. Se crea compra_practica.csv en la carpeta de trabajo.", "tip": "La extensión CSV no garantiza separador, codificación o tipos. Inspecciona el archivo antes de interpretarlo."}, {"title": "Leer un error sin perder el contexto", "text": ["ValueError suele aparecer cuando una conversión recibe un valor incompatible. KeyError señala una clave inexistente; NameError, un nombre no definido.", "Captura errores específicos cuando puedas responder a ellos. Un except general que no informa nada puede esconder problemas. Registra qué no se pudo convertir."], "code": "entradas = [\"4\", \"sin dato\", \"8\"]\nfor texto in entradas:\n    try:\n        numero = int(texto)\n        print(numero)\n    except ValueError:\n        print(\"No se pudo convertir:\", texto)", "output": "4; No se pudo convertir: sin dato; 8.", "tip": "Un notebook reproducible incluye importaciones, rutas, decisiones y resultados, y se ejecuta completo después de reiniciar."}], "tasks": [{"title": "Reconocer el problema", "prompt": "Convierte \"15.5\" a decimal. Luego intenta convertir \"quince\" y muestra un mensaje útil sin detener la ejecución.", "check": "15.5 y un mensaje sobre el texto inválido.", "hint": "Captura ValueError.", "solution": "for texto in [\"15.5\", \"quince\"]:\n    try:\n        print(float(texto))\n    except ValueError:\n        print(\"Número inválido:\", texto)", "explanation": "El error se comunica; no se reemplaza silenciosamente por cero."}, {"title": "Documenta un archivo", "prompt": "Usa Path para mostrar el nombre y la extensión de datos/ventas.csv. No necesitas abrir el archivo.", "check": "ventas.csv y .csv.", "hint": "Consulta name y suffix.", "solution": "from pathlib import Path\np = Path(\"datos\") / \"ventas.csv\"\nprint(p.name)\nprint(p.suffix)", "explanation": "Construir una ruta no crea el archivo ni comprueba que exista."}], "quiz": [{"question": "¿Qué significa NameError?", "options": ["Un nombre no está definido", "El archivo es muy grande", "La tabla tiene duplicados"], "answer": 0, "explanation": "Comprueba la escritura del nombre y la ejecución de su celda."}, {"question": "¿Qué hace una ruta relativa?", "options": ["Se interpreta desde la carpeta de trabajo", "Siempre apunta a Descargas", "Funciona solo en Windows"], "answer": 0, "explanation": "La carpeta de trabajo determina cómo se resuelve una ruta relativa."}, {"question": "¿Qué conviene hacer ante un dato inválido?", "options": ["Ocultarlo siempre", "Convertirlo siempre a cero", "Detectarlo y documentar su tratamiento"], "answer": 2, "explanation": "Cero puede ser un dato real; no debe sustituir automáticamente una ausencia o error."}], "homework": {"title": "Entrega reproducible", "context": "Reorganiza uno de tus notebooks anteriores para que otra persona pueda ejecutarlo.", "steps": ["Coloca las importaciones y datos al principio.", "Agrega una celda de texto con objetivo, entradas y unidades.", "Reinicia y ejecuta todo; corrige nombres y orden.", "Describe un error que encontraste y cómo lo resolviste."]}, "badge": 1}, {"id": 5, "title": "Descubre Pandas", "short": "Series y DataFrames", "phase": "Badge 2 · Analista con Pandas", "description": "Construye una tabla, carga un CSV y aprende a inspeccionarlo antes de analizar.", "objectives": ["Crear Series y DataFrames.", "Inspeccionar forma, columnas y tipos.", "Leer y exportar archivos CSV."], "lessons": [{"title": "Series y DataFrame", "text": ["Una Series combina valores con un índice. Un DataFrame es una tabla de columnas que comparten un índice de filas. Los nombres de columnas describen variables y cada fila representa una observación.", "Al construir una tabla con listas, cada columna debe tener la misma longitud. El significado de una fila depende del conjunto de datos: producto, persona o registro de venta."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos)\nprint(type(productos[\"Precio\"]).__name__)", "output": "Una tabla con tres filas y tres columnas; seleccionar Precio devuelve una Series.", "tip": "El índice identifica filas en la tabla. No necesariamente representa un identificador de negocio."}, {"title": "Inspeccionar antes de operar", "text": ["head muestra las primeras filas; shape devuelve dimensiones; columns contiene nombres; info resume tipos y valores no nulos. Una vista inicial ayuda a detectar problemas antes de sumar.", "Una selección con un nombre devuelve una Series. Una selección con una lista de nombres devuelve un DataFrame, incluso si esa lista contiene un único nombre."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos.head(2))\nprint(productos.shape)\nprint(productos.columns.tolist())\nproductos.info()\nprint(productos[[\"Producto\", \"Precio\"]])", "output": "Forma (3, 3). Precio es numérico decimal; Cantidad es entera.", "tip": "shape y columns son atributos, sin paréntesis. head e info son métodos, con paréntesis."}, {"title": "Leer y exportar CSV", "text": ["read_csv interpreta un archivo y crea una tabla. Revisa siempre el separador, las columnas y los tipos. El archivo ventas.csv del curso contiene cinco registros; su moneda no está especificada.", "Al exportar, index=False evita guardar el índice como una columna adicional. Para Excel se usa read_excel o to_excel y se requiere un motor compatible, como openpyxl para xlsx."], "code": "import pandas as pd\nfrom pathlib import Path\n\nDATOS = next((p for p in [Path(\"datos\"), Path(\"../datos\"), Path(\".\")]\n              if (p / \"ventas.csv\").exists()), Path(\"datos\"))\nventas = pd.read_csv(DATOS / \"ventas.csv\")\nprint(ventas.shape)\nventas.to_csv(\"ventas_copia.csv\", index=False)\nprint(\"Copia exportada\")", "output": "(5, 4) y un archivo ventas_copia.csv en la carpeta de trabajo.", "tip": "Conserva el archivo original. Exporta a un nombre nuevo para mantener una referencia verificable."}], "tasks": [{"title": "Tu primera tabla", "prompt": "Crea una tabla con Nombre [Ana, Luis, Marta] y Edad [28, 34, 42]. Muestra dimensiones y nombres.", "check": "(3, 2) y una columna con los tres nombres.", "hint": "Usa un diccionario de listas.", "solution": "import pandas as pd\npersonas = pd.DataFrame({\"Nombre\": [\"Ana\", \"Luis\", \"Marta\"], \"Edad\": [28, 34, 42]})\nprint(personas.shape)\nprint(personas[\"Nombre\"])", "explanation": "Las listas tienen tres elementos y se alinean por posición."}, {"title": "Una columna, dos estructuras", "prompt": "Selecciona Precio de productos como Series y como DataFrame. Imprime ambos tipos.", "check": "Series y DataFrame.", "hint": "Compara un nombre con una lista que contiene ese nombre.", "solution": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(type(productos[\"Precio\"]).__name__)\nprint(type(productos[[\"Precio\"]]).__name__)", "explanation": "Los corchetes externos seleccionan; los internos construyen una lista de nombres."}], "quiz": [{"question": "¿Qué devuelve shape?", "options": ["Nombres de columnas", "Cantidad de filas y columnas", "Promedios"], "answer": 1, "explanation": "shape describe las dimensiones de la tabla."}, {"question": "¿Qué evita index=False al exportar?", "options": ["Guardar el índice como columna adicional", "Guardar encabezados", "Guardar números"], "answer": 0, "explanation": "Las columnas del DataFrame se exportan sin añadir su índice."}, {"question": "¿Qué debes hacer primero al cargar un archivo?", "options": ["Eliminar filas al azar", "Inspeccionar estructura y tipos", "Entrenar un modelo"], "answer": 1, "explanation": "La inspección ayuda a conocer la unidad de observación y problemas de lectura."}], "homework": {"title": "Radiografía de ventas.csv", "context": "Usa el archivo original del curso.", "steps": ["Carga el CSV e identifica qué representa cada fila.", "Muestra primeras filas, dimensiones y tipos.", "Selecciona Producto y Cantidad.", "Exporta la selección a seleccion_ventas.csv, sin índice. Control: 5 filas y 2 columnas."]}, "badge": 2}, {"id": 6, "title": "Encuentra lo que necesitas", "short": "Selección y filtros", "phase": "Badge 2 · Analista con Pandas", "description": "Consulta filas por etiquetas o posiciones y formula filtros que respondan preguntas.", "objectives": ["Distinguir loc e iloc.", "Combinar condiciones correctamente.", "Crear columnas y ordenar resultados."], "lessons": [{"title": "loc e iloc: dos coordenadas distintas", "text": ["loc accede por etiquetas y acepta condiciones booleanas. iloc accede por posiciones enteras desde cero. Una etiqueta puede ser texto o un número; no debe confundirse con una posición.", "En el índice único y ordenado de este ejemplo, loc incluye la etiqueta final de un rango. iloc excluye la posición final."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos.loc[\"p2\", \"Precio\"])\nprint(productos.iloc[1, 1])\nprint(productos.loc[\"p1\":\"p2\"])\nprint(productos.iloc[0:2])", "output": "Ambos accesos individuales devuelven 25.5; ambos rangos seleccionan Mouse y Teclado.", "tip": "Tras ordenar una tabla, la posición de una fila puede cambiar mientras su etiqueta permanece."}, {"title": "Filtros: convierte una pregunta en condición", "text": ["Una comparación de columna produce una máscara booleana. Para combinar condiciones en Pandas usa & para “y”, | para “o”, y paréntesis alrededor de cada comparación.", "Filtrar devuelve los registros que cumplen la regla. Especificar las columnas con loc permite mostrar solo la información necesaria."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\ncondicion = (productos[\"Precio\"] < 100) & (productos[\"Cantidad\"] >= 2)\nprint(productos.loc[condicion, [\"Producto\", \"Cantidad\"]])", "output": "Mouse con 3 unidades y Teclado con 2.", "tip": "En condiciones de Pandas no sustituyas & por and: and no combina Series elemento por elemento."}, {"title": "Derivar, modificar y ordenar", "text": ["Una nueva columna puede calcularse a partir de columnas existentes. Para modificar valores según una condición, usa una sola operación loc y evita asignaciones encadenadas.", "sort_values crea una tabla ordenada por valores. Guardamos el resultado en otra variable para conservar la referencia original."], "code": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nproductos[\"Ingreso\"] = productos[\"Precio\"] * productos[\"Cantidad\"]\nproductos.loc[productos[\"Producto\"] == \"Mouse\", \"Cantidad\"] = 4\n# Recalcular porque cambió una entrada del cálculo.\nproductos[\"Ingreso\"] = productos[\"Precio\"] * productos[\"Cantidad\"]\nordenados = productos.sort_values(\"Ingreso\", ascending=False)\nprint(ordenados[[\"Producto\", \"Ingreso\"]])", "output": "Monitor 199.99; Mouse 63.96; Teclado 51.00.", "tip": "Una columna calculada no es una fórmula de hoja de cálculo: si cambias sus entradas, debes volver a calcularla."}], "tasks": [{"title": "Selecciona el monitor", "prompt": "Obtén el monitor con loc y luego con iloc. Consulta solo su precio.", "check": "199.99 en ambos casos.", "hint": "La etiqueta es p3 y la posición es 2.", "solution": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nprint(productos.loc[\"p3\", \"Precio\"])\nprint(productos.iloc[2, 1])", "explanation": "La columna Precio ocupa la posición 1."}, {"title": "Compra de varias unidades", "prompt": "Filtra cantidades >= 2 y muestra productos ordenados por Precio de menor a mayor.", "check": "Mouse y Teclado, en ese orden.", "hint": "Filtra primero y ordena el resultado.", "solution": "import pandas as pd\n\nproductos = pd.DataFrame({\n    \"Producto\": [\"Mouse\", \"Teclado\", \"Monitor\"],\n    \"Precio\": [15.99, 25.50, 199.99],\n    \"Cantidad\": [3, 2, 1]\n}, index=[\"p1\", \"p2\", \"p3\"])\nseleccion = productos.loc[productos[\"Cantidad\"] >= 2]\nprint(seleccion.sort_values(\"Precio\")[[\"Producto\", \"Precio\"]])", "explanation": "Se ordenan solo los registros que cumplen la condición."}], "quiz": [{"question": "¿Qué busca tabla.loc[10]?", "options": ["La décima fila", "La etiqueta 10", "La posición 10"], "answer": 1, "explanation": "loc interpreta 10 como etiqueta."}, {"question": "¿Qué operador combina dos condiciones de Series con “y”?", "options": ["and", "&", "+"], "answer": 1, "explanation": "Usa & y rodea cada comparación con paréntesis."}, {"question": "Si cambia Precio, ¿Ingreso se actualiza solo?", "options": ["Sí, siempre", "No, debes recalcularlo", "Solo si está ordenado"], "answer": 1, "explanation": "La asignación almacena valores calculados en ese momento."}], "homework": {"title": "Consultas de librería", "context": "Construye una tabla: Cuaderno 1500×4, Lapicero 500×10, Carpeta 1200×3, Marcador 800×5, Regla 600×2.", "steps": ["Selecciona productos cuyo precio supere ₡700.", "Crea Ingreso y suma el total.", "Ordena por ingreso descendente en otra variable.", "Escribe dos conclusiones. Control: total ₡19 800; mayor ingreso Cuaderno, ₡6000."]}, "badge": 2}, {"id": 7, "title": "Antes de analizar, limpia", "short": "Calidad de datos", "phase": "Badge 2 · Analista con Pandas", "description": "Detecta inconsistencias y toma decisiones que puedas explicar y auditar.", "objectives": ["Reconocer faltantes y duplicados.", "Normalizar texto y convertir tipos.", "Documentar qué cambió y por qué."], "lessons": [{"title": "Ausencias y duplicados no son lo mismo", "text": ["Un valor faltante significa que no tenemos un dato. Un duplicado puede ser un registro cargado dos veces, pero también dos eventos válidos parecidos. Decide usando una clave de negocio.", "Antes de borrar, cuenta y revisa. En este ejemplo id identifica la venta; la segunda aparición de id 2 es una copia exacta del mismo registro."], "code": "import pandas as pd\n\ndatos = pd.DataFrame({\"id\": [1, 2, 2, 3], \"Cantidad\": [4, 2, 2, None]})\nprint(datos.isna().sum())\nprint(\"Duplicados exactos:\", datos.duplicated().sum())\nlimpios = datos.drop_duplicates().copy()\nprint(limpios)", "output": "Cantidad tiene 1 faltante. Hay 1 duplicado exacto. Quedan tres filas.", "tip": "No rellenes todas las ausencias con cero: una cantidad desconocida no equivale a una venta de cero unidades."}, {"title": "Texto consistente, categorías útiles", "text": ["Mayúsculas y espacios pueden dividir una misma categoría en varias. str.strip elimina espacios en los extremos; str.lower convierte a minúsculas. Conserva el texto original en otra columna.", "Normalizar no resuelve todos los casos. Abreviaturas, errores ortográficos y categorías ambiguas requieren reglas explícitas y revisión."], "code": "import pandas as pd\n\nencuesta = pd.DataFrame({\"respuesta\": [\"Buena\", \" buena \", \"MALA\", \"mala\"]})\nencuesta[\"respuesta_limpia\"] = encuesta[\"respuesta\"].str.strip().str.lower()\nprint(encuesta[\"respuesta_limpia\"].value_counts())", "output": "buena: 2; mala: 2.", "tip": "Documenta las reglas aplicadas. Cambiar el texto sin conservar el original dificulta revisar decisiones."}, {"title": "Tipos y rangos: convertir también revela problemas", "text": ["to_numeric con errors=\"coerce\" convierte entradas inválidas en faltantes. Eso permite detectarlas, pero no corrige su significado. La cantidad de nuevas ausencias es parte del informe de calidad.", "Un valor atípico puede ser un error o un caso real importante. Primero investiga la unidad, la fuente y el contexto. No lo elimines solo por ser grande."], "code": "import pandas as pd\n\ndatos = pd.DataFrame({\"Cantidad_original\": [\"4\", \"sin dato\", \"-2\", \"100\"]})\ndatos[\"Cantidad\"] = pd.to_numeric(datos[\"Cantidad_original\"], errors=\"coerce\")\nprint(datos)\nprint(\"Inválidos o ausentes:\", datos[\"Cantidad\"].isna().sum())\nprint(\"Negativos:\", (datos[\"Cantidad\"] < 0).sum())", "output": "Se detecta un texto inválido y una cantidad negativa. 100 es grande, pero no necesariamente incorrecto.", "tip": "Una cantidad negativa podría ser una devolución. El diccionario de datos debe aclarar si está permitida."}], "tasks": [{"title": "Limpia categorías", "prompt": "Normaliza [\" TI\", \"ti \", \"Ventas\", \"VENTAS \"] y cuenta las respuestas.", "check": "ti: 2; ventas: 2.", "hint": "Usa Series.str.strip y str.lower.", "solution": "import pandas as pd\ns = pd.Series([\" TI\", \"ti \", \"Ventas\", \"VENTAS \"])\nprint(s.str.strip().str.lower().value_counts())", "explanation": "La limpieza reúne representaciones distintas de las mismas categorías."}, {"title": "Separa para revisión", "prompt": "Convierte [\"10\", \"?\", \"20\"] a números. Guarda los valores inválidos en una selección.", "check": "Un registro para revisar; valores válidos suman 30.", "hint": "isna identifica la conversión fallida.", "solution": "import pandas as pd\ndf = pd.DataFrame({\"original\": [\"10\", \"?\", \"20\"]})\ndf[\"numero\"] = pd.to_numeric(df[\"original\"], errors=\"coerce\")\nprint(df.loc[df[\"numero\"].isna()])\nprint(df[\"numero\"].sum())", "explanation": "La suma ignora el faltante por defecto; informa que excluye una observación."}], "quiz": [{"question": "¿Un dato faltante siempre equivale a cero?", "options": ["Sí", "No", "Solo en texto"], "answer": 1, "explanation": "La ausencia representa falta de información; cero tiene significado propio."}, {"question": "¿Qué hace errors=\"coerce\"?", "options": ["Inventa el dato correcto", "Convierte valores inválidos en faltantes", "Elimina toda la tabla"], "answer": 1, "explanation": "Después de convertir debes identificar y documentar los casos afectados."}, {"question": "¿Qué hacer con un valor extremo?", "options": ["Borrarlo automáticamente", "Investigar su contexto", "Reemplazarlo siempre por la media"], "answer": 1, "explanation": "Un extremo puede ser válido. Su tratamiento depende del contexto y el objetivo."}], "homework": {"title": "Una encuesta consistente", "context": "Carga encuesta.csv del curso.", "steps": ["Cuenta categorías originales y revisa espacios y mayúsculas.", "Crea satisfaccion_limpia sin sobrescribir satisfaccion.", "Cuenta respuestas limpias y comprueba el número total de filas.", "Describe la diferencia: 6 representaciones originales, 3 categorías limpias y 6 respuestas conservadas."]}, "badge": 2}, {"id": 8, "title": "Agrupa, resume y devuelve contexto", "short": "groupby a fondo", "phase": "Badge 2 · Analista con Pandas", "description": "Distingue agregación, transformación y selección de grupos, con controles de conservación.", "objectives": ["Usar agg con varias métricas.", "Conservar filas con transform.", "Controlar claves faltantes y filtros de grupos."], "lessons": [{"title": "Agrupar para responder una pregunta", "text": ["groupby divide registros según una o varias claves. Una agregación resume cada grupo con sum, mean, count u otra operación. Elige el resumen según la pregunta.", "Sumar cantidades devuelve unidades; contar filas devuelve registros. Son indicadores diferentes, aunque a veces tengan el mismo valor."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"Producto\": [\"Mouse\", \"Mouse\", \"Teclado\"],\n                      \"Cantidad\": [3, 1, 2], \"Ingreso\": [47.97, 15.99, 51.0]})\nresumen = ventas.groupby(\"Producto\", as_index=False).agg(\n    unidades=(\"Cantidad\", \"sum\"),\n    ingreso=(\"Ingreso\", \"sum\"),\n    registros=(\"Producto\", \"size\")\n)\nprint(resumen)", "output": "Mouse: 4 unidades, 63.96 de ingreso y 2 registros. Teclado: 2, 51.00 y 1.", "tip": "Un promedio de precios por registro no es lo mismo que el precio promedio ponderado por unidades."}, {"title": "transform: una estadística por fila", "text": ["agg reduce cada grupo a un resumen; transform devuelve un resultado alineado con las filas originales. Sirve para añadir el total del grupo y calcular la participación de cada registro.", "Prefiere transform y operaciones vectorizadas para cálculos conocidos. apply es flexible, pero puede ser menos claro y eficiente. Define cómo tratar un grupo cuyo total sea cero antes de dividir."], "code": "import pandas as pd\nv=pd.DataFrame({\"Producto\":[\"A\",\"A\",\"B\"],\"Ingreso\":[10,30,20]})\nv[\"TotalGrupo\"]=v.groupby(\"Producto\")[\"Ingreso\"].transform(\"sum\")\nv[\"Participacion\"]=v.Ingreso/v.TotalGrupo\nprint(v)", "output": "A: participaciones 0.25 y 0.75; B: 1.0. Se conservan 3 filas.", "tip": "transform añade contexto de grupo sin perder la granularidad original."}, {"title": "filter y claves ausentes", "text": ["filter conserva grupos completos según una condición. No equivale a filtrar filas por su valor individual: un grupo puede conservar todas sus filas aunque algunas sean pequeñas.", "groupby omite claves faltantes por defecto. Usa dropna=False si quieres incluir un grupo para ellas, y compara totales. size cuenta filas; count cuenta valores no nulos en la columna seleccionada."], "code": "import pandas as pd\nv=pd.DataFrame({\"Grupo\":[\"A\",\"A\",\"B\",None],\"Valor\":[10,30,20,5]})\nprint(v.groupby(\"Grupo\",dropna=False).Valor.sum())\nprint(v.groupby(\"Grupo\",dropna=False).filter(lambda g: len(g)>=2))\nassert v.groupby(\"Grupo\",dropna=False).Valor.sum().sum()==v.Valor.sum()", "output": "Total conservado 65. filter conserva las dos filas de A.", "tip": "Una suma por grupos puede perder observaciones si hay claves faltantes y no revisas dropna."}], "tasks": [{"title": "Total por producto", "prompt": "Agrupa A, B, A con ingresos 100, 200, 50. Ordena los totales de mayor a menor.", "check": "B: 200; A: 150.", "hint": "groupby seguido de sum y sort_values.", "solution": "import pandas as pd\nv = pd.DataFrame({\"Producto\": [\"A\", \"B\", \"A\"], \"Ingreso\": [100, 200, 50]})\nprint(v.groupby(\"Producto\")[\"Ingreso\"].sum().sort_values(ascending=False))", "explanation": "Primero se agregan registros de un mismo producto; luego se comparan sus totales."}, {"title": "Porcentaje dentro del producto", "prompt": "Para A=[10,30] y B=[20], añade participaciones por fila.", "solution": "import pandas as pd\nv=pd.DataFrame({\"p\":[\"A\",\"A\",\"B\"],\"x\":[10,30,20]})\nv[\"porcentaje\"]=100*v.x/v.groupby(\"p\").x.transform(\"sum\")\nprint(v)", "check": "25 %, 75 %, 100 %.", "hint": "Usa transform(\"sum\") como denominador.", "explanation": "25 %, 75 %, 100 %."}], "quiz": [{"question": "¿Qué mide size en un grupo?", "options": ["Número de registros", "Suma monetaria", "Precio unitario"], "answer": 0, "explanation": "size cuenta filas, no unidades vendidas."}, {"question": "¿Qué preserva transform?", "options": ["La alineación con las filas originales", "Solo una fila por grupo", "Únicamente columnas de texto"], "answer": 0, "explanation": "Devuelve estadísticas alineadas para enriquecer cada observación."}, {"question": "¿Qué implica dropna=False en groupby?", "options": ["Incluye claves faltantes como grupo", "Reemplaza todas las ausencias por cero", "Elimina faltantes"], "answer": 0, "explanation": "Permite contabilizar registros que de otro modo quedarían fuera de los grupos."}], "homework": {"title": "Indicadores por producto", "context": "Usa ventas.csv, calcula Ingreso y mantén una copia original.", "steps": ["Calcula unidades, ingresos y registros con agg.", "Añade participación de cada venta en el ingreso del producto con transform.", "Selecciona grupos con al menos dos registros.", "Introduce una clave faltante y demuestra cómo dropna afecta la conservación del total."]}, "badge": 2}, {"title": "Combina tablas sin perder el control", "short": "merge y concat", "description": "Integra archivos y catálogos con claves, índices y comprobaciones explícitas.", "objectives": ["Distinguir concatenación y unión por claves.", "Comparar left, inner y outer.", "Detectar multiplicaciones de filas y claves sin pareja."], "lessons": [{"title": "concat: apilar archivos y alinear índices", "text": ["concat con axis=0 reúne filas y alinea columnas por nombre. ignore_index=True crea un índice consecutivo, pero no elimina registros duplicados. Agrega una columna de origen antes de combinar para conservar trazabilidad.", "Con axis=1 se agregan columnas alineadas por etiqueta del índice; no por la posición que ves en pantalla. Una etiqueta ausente en uno de los objetos produce un faltante. Revisa los esquemas y concatena una lista de tablas de una sola vez."], "code": "import pandas as pd\na = pd.DataFrame({\"Producto\": [\"A\", \"B\"], \"Unidades\": [2, 3]})\nb = pd.DataFrame({\"Producto\": [\"A\"], \"Unidades\": [4]})\nunidas = pd.concat([a.assign(Origen=\"enero\"), b.assign(Origen=\"febrero\")], ignore_index=True)\nprint(unidas)\nprint(unidas[\"Unidades\"].sum())", "output": "Tres registros; total 9 unidades.", "tip": "concat une estructuras sobre un eje; no busca claves de negocio como merge."}, {"title": "merge: elegir qué registros conservar", "text": ["Una unión inner conserva claves presentes en ambos lados; left conserva todas las filas izquierdas; outer conserva claves de ambos lados. on nombra la clave. Si sus nombres difieren, usa left_on y right_on.", "indicator crea _merge para identificar coincidencias y ausencias. Pandas puede hacer coincidir claves nulas entre sí: revisa y trata las claves faltantes antes de unir, especialmente si vienes de SQL."], "code": "import pandas as pd\nv = pd.DataFrame({\"id\": [1, 2, 3], \"Unidades\": [2, 4, 1]})\nc = pd.DataFrame({\"id\": [1, 2, 4], \"Categoria\": [\"A\", \"B\", \"C\"]})\nfor tipo in [\"inner\", \"left\", \"outer\"]:\n    u = v.merge(c, on=\"id\", how=tipo, validate=\"one_to_one\", indicator=True)\n    print(tipo, len(u))\nprint(v.merge(c, on=\"id\", how=\"left\", indicator=True))", "output": "inner: 2 filas; left: 3; outer: 4. La clave 3 queda left_only.", "tip": "Elige how según el universo que deseas conservar, no según el resultado que se vea más completo."}, {"title": "Cardinalidad: la defensa contra totales inflados", "text": ["Una relación many_to_one admite muchas ventas para un solo producto de catálogo. validate verifica esa expectativa y falla si el catálogo tiene claves duplicadas. Un many_to_many puede producir todas las combinaciones de coincidencias.", "Compara cantidad de filas y suma de unidades antes y después de enriquecer ventas. Usa suffixes si ambos lados contienen columnas de igual nombre y selecciona explícitamente cuál representa el indicador correcto."], "code": "import pandas as pd\nv = pd.DataFrame({\"id\": [1, 1, 2], \"Unidades\": [2, 3, 4]})\nc = pd.DataFrame({\"id\": [1, 2], \"Nombre\": [\"A\", \"B\"]})\nu = v.merge(c, on=\"id\", how=\"left\", validate=\"many_to_one\")\nassert len(u) == len(v)\nassert u.Unidades.sum() == v.Unidades.sum()\nprint(u.Unidades.sum())", "output": "Total conservado: 9.", "tip": "No quites validate para silenciar un error: investiga primero las claves."}], "tasks": [{"title": "Archivos mensuales", "prompt": "Concatena cantidades [2,3] y [4], conservando origen.", "solution": "import pandas as pd\na=pd.DataFrame({\"q\":[2,3]}).assign(mes=\"enero\")\nb=pd.DataFrame({\"q\":[4]}).assign(mes=\"febrero\")\nu=pd.concat([a,b],ignore_index=True)\nprint(u)\nassert u.q.sum()==9", "check": "3 filas y 9 unidades.", "hint": "Usa assign antes de concat.", "explanation": "3 filas y 9 unidades."}, {"title": "Una clave sin catálogo", "prompt": "Une claves [1,2] con un catálogo que solo tiene 1. Identifica la ausencia.", "solution": "import pandas as pd\na=pd.DataFrame({\"id\":[1,2]})\nb=pd.DataFrame({\"id\":[1],\"nombre\":[\"A\"]})\nu=a.merge(b,on=\"id\",how=\"left\",validate=\"many_to_one\",indicator=True)\nprint(u.loc[u._merge==\"left_only\"])", "check": "La clave 2 no tiene correspondencia.", "hint": "Utiliza indicator=True.", "explanation": "La clave 2 no tiene correspondencia."}], "quiz": [{"question": "¿concat elimina duplicados?", "options": ["Sí", "No", "Solo con ignore_index"], "answer": 1, "explanation": "ignore_index cambia etiquetas; no elimina filas repetidas."}, {"question": "¿Qué unión conserva todas las filas izquierdas?", "options": ["inner", "left", "Ninguna"], "answer": 1, "explanation": "left conserva el universo de la izquierda."}, {"question": "¿Qué comprueba many_to_one?", "options": ["Unicidad de la clave derecha", "Que ambas tablas tengan igual largo", "Ausencia de valores cero"], "answer": 0, "explanation": "Muchas filas izquierdas pueden apuntar a una clave derecha única."}], "homework": {"title": "Laboratorio · merge y concat", "context": "Integra archivos y catálogos con claves, índices y comprobaciones explícitas.", "steps": ["Divide ventas.csv en dos archivos y vuelve a unirlos con concat y columna de origen.", "Crea un catálogo y enriquece con merge many_to_one.", "Agrega deliberadamente una clave repetida al catálogo y documenta el error de validación.", "Entrega un control de filas, unidades y claves sin correspondencia."]}, "id": 9, "badge": 2, "phase": "Badge 2 · Analista con Pandas"}, {"title": "Cambia la forma, conserva el significado", "short": "stack y unstack", "description": "Trabaja con formato largo, ancho y niveles de índice sin confundir reorganización con agregación.", "objectives": ["Construir e interpretar un MultiIndex.", "Mover niveles con stack y unstack.", "Elegir melt, pivot o pivot_table."], "lessons": [{"title": "MultiIndex: más de una etiqueta", "text": ["Un MultiIndex identifica una observación mediante varias claves, por ejemplo Sucursal y Mes. set_index crea esos niveles y sort_index facilita una lectura ordenada. reset_index devuelve las claves a columnas.", "La combinación de claves debe ser única si quieres reorganizar sin agregar. Si hay varias ventas en una combinación sucursal–mes, primero define cómo resumirlas."], "code": "import pandas as pd\ndf=pd.DataFrame({\"Sucursal\":[\"Norte\",\"Norte\",\"Sur\",\"Sur\"],\"Mes\":[\"ene\",\"feb\",\"ene\",\"feb\"],\"Ingreso\":[10,20,30,40]})\ns=df.set_index([\"Sucursal\",\"Mes\"])[\"Ingreso\"].sort_index()\nprint(s)\nprint(s.loc[(\"Norte\",\"ene\")])", "output": "Norte en enero tiene ingreso 10.", "tip": "Un MultiIndex expresa una estructura; no resume datos por sí solo."}, {"title": "stack y unstack: mover niveles", "text": ["unstack mueve un nivel del índice hacia las columnas. stack mueve un nivel de columnas hacia el índice. Selecciona el nivel por nombre para hacer visible tu intención.", "Una combinación no observada puede convertirse en faltante. fill_value=0 solo es correcto cuando ausencia de observación significa cero según el negocio. Al regresar, compara claves y valores, no solo el orden visual."], "code": "import pandas as pd\ns=pd.Series([10,20,30,40],index=pd.MultiIndex.from_tuples([(\"Norte\",\"ene\"),(\"Norte\",\"feb\"),(\"Sur\",\"ene\"),(\"Sur\",\"feb\")],names=[\"Sucursal\",\"Mes\"]))\nancho=s.unstack(\"Mes\")\nlargo=ancho.stack()\nprint(ancho)\nassert largo.sort_index().equals(s.sort_index())\nprint(\"Valores y claves conservados\")", "output": "Tabla de 2 sucursales × 2 meses; se recuperan los cuatro valores.", "tip": "stack/unstack reorganizan niveles. No reemplazan una suma o un promedio."}, {"title": "melt, pivot y pivot_table", "text": ["melt convierte columnas de medidas en filas y conserva columnas identificadoras. pivot hace la operación inversa si cada combinación de claves corresponde a un solo valor.", "pivot_table permite resumir repeticiones mediante aggfunc. No uses su promedio predeterminado sin pensar: para ingresos acumulados, suele corresponder sum."], "code": "import pandas as pd\nancho=pd.DataFrame({\"Producto\":[\"A\",\"B\"],\"ene\":[10,20],\"feb\":[15,25]})\nlargo=ancho.melt(id_vars=\"Producto\",var_name=\"Mes\",value_name=\"Ingreso\")\nprint(largo)\nprint(largo.pivot(index=\"Producto\",columns=\"Mes\",values=\"Ingreso\"))", "output": "Cuatro filas en formato largo y dos productos en la tabla recuperada.", "tip": "Si pivot falla por duplicados, decide si deben investigarse o agregarse; no elijas una función arbitraria."}], "tasks": [{"title": "De meses a columnas", "prompt": "Crea una Series MultiIndex A/ene=10, A/feb=20 y aplica unstack.", "solution": "import pandas as pd\ns=pd.Series([10,20],index=pd.MultiIndex.from_tuples([(\"A\",\"ene\"),(\"A\",\"feb\")],names=[\"Producto\",\"Mes\"]))\nprint(s.unstack(\"Mes\"))", "check": "Una fila y dos columnas.", "hint": "Mueve el nivel Mes.", "explanation": "Una fila y dos columnas."}, {"title": "Deshacer el formato ancho", "prompt": "Usa melt sobre A: ene=10, feb=20.", "solution": "import pandas as pd\ndf=pd.DataFrame({\"Producto\":[\"A\"],\"ene\":[10],\"feb\":[20]})\nprint(df.melt(id_vars=\"Producto\",var_name=\"Mes\",value_name=\"Ingreso\"))", "check": "Dos registros de ingreso para A.", "hint": "Producto es la columna identificadora.", "explanation": "Dos registros de ingreso para A."}], "quiz": [{"question": "¿Qué hace unstack?", "options": ["Mueve un nivel de índice a columnas", "Suma siempre", "Borra duplicados"], "answer": 0, "explanation": "Reorganiza etiquetas entre ejes."}, {"question": "¿Cuándo pivot puede fallar?", "options": ["Con claves repetidas para la misma celda", "Con enteros", "Siempre que hay dos columnas"], "answer": 0, "explanation": "pivot exige una combinación única para cada celda."}, {"question": "¿Un faltante debe rellenarse con cero?", "options": ["Siempre", "Solo si el significado lo justifica", "Nunca hay faltantes"], "answer": 1, "explanation": "No observado y cero son conceptos diferentes."}], "homework": {"title": "Laboratorio · stack y unstack", "context": "Trabaja con formato largo, ancho y niveles de índice sin confundir reorganización con agregación.", "steps": ["Construye ingresos de dos sucursales y tres meses.", "Crea MultiIndex y muestra versiones con stack/unstack.", "Comprueba la conservación de valores tras regresar al formato original.", "Agrega una observación repetida y explica cuándo usar pivot_table con sum."]}, "id": 10, "badge": 2, "phase": "Badge 2 · Analista con Pandas"}, {"title": "Analiza datos a lo largo del tiempo", "short": "Series de tiempo", "description": "Ordena fechas, distingue frecuencia de agregación y calcula indicadores temporales sin mirar el futuro.", "objectives": ["Construir un DatetimeIndex.", "Comparar resample y asfreq.", "Usar shift, rolling y expanding."], "lessons": [{"title": "Fechas, orden y zona horaria", "text": ["Convierte fechas con un formato explícito y revisa errores antes de crear un DatetimeIndex. Ordena cronológicamente: una ventana por tiempo depende del orden y la duración, no del orden de llegada del archivo.", "tz_localize asigna una zona a fechas sin zona; tz_convert transforma instantes que ya tienen zona. Define la zona de la fuente antes de juntar datos; utc=True no debe reinterpretar sin análisis una hora local."], "code": "import pandas as pd\ndf=pd.DataFrame({\"Fecha\":[\"2026-01-03\",\"2026-01-01\"],\"Ingreso\":[30,10]})\ndf[\"Fecha\"]=pd.to_datetime(df.Fecha,format=\"%Y-%m-%d\")\ns=df.set_index(\"Fecha\").sort_index()[\"Ingreso\"]\nprint(s)\nprint(s.index.tz_localize(\"America/Costa_Rica\").tz_convert(\"UTC\"))", "output": "Primero aparece enero 1; medianoche de Costa Rica corresponde a 06:00 UTC en estas fechas.", "tip": "Conserva la definición de fecha local o instante: no representan lo mismo."}, {"title": "resample agrega; asfreq cambia la grilla", "text": ["resample agrupa observaciones en intervalos temporales y requiere una agregación. asfreq coloca la serie sobre una frecuencia y puede crear huecos sin resumir valores.", "Define qué significa un día sin registro. sum(min_count=1) conserva como faltante un intervalo vacío. Para promedios diarios, los días desconocidos no deben convertirse en días con cero ventas sin justificación."], "code": "import pandas as pd\ns=pd.Series([10,30],index=pd.to_datetime([\"2026-01-01\",\"2026-01-03\"]))\nprint(s.asfreq(\"D\"))\nprint(s.resample(\"D\").sum(min_count=1))\nprint(s.resample(\"MS\").sum(min_count=1))", "output": "Enero 2 aparece como NaN; el ingreso observado de enero suma 40.", "tip": "Informa cobertura y períodos parciales; un total mensual no garantiza que todos los días estén observados."}, {"title": "Rezagos, ventanas y acumulados", "text": ["shift(1) desplaza valores una observación y permite crear un rezago. rolling(3) usa tres observaciones; rolling(\"3D\") usa una duración temporal y puede incluir cantidades distintas de registros. min_periods controla cuántos datos válidos se requieren.", "expanding usa todos los datos disponibles hasta cada punto. Para una variable que pretende predecir el presente, calcula estadísticas con datos anteriores: shift(1).rolling(...). Evita ventanas centradas que incorporen el futuro."], "code": "import pandas as pd\ns=pd.Series([10,20,30,40],index=pd.date_range(\"2026-01-01\",periods=4,freq=\"D\"))\nprint(s.rolling(3,min_periods=3).mean())\nprint(s.shift(1).rolling(2,min_periods=2).mean())\nprint(s.expanding().mean())", "output": "Media de 3: NaN, NaN, 20, 30. Media de 2 anteriores: NaN, NaN, 15, 25. Acumulada: 10, 15, 20, 25.", "tip": "Ventanas por observaciones y por tiempo solo coinciden bajo ciertas frecuencias y ausencia de huecos."}], "tasks": [{"title": "Encuentra el día faltante", "prompt": "Reindexa a días la serie con enero 1=10 y enero 3=30.", "solution": "import pandas as pd\ns=pd.Series([10,30],index=pd.to_datetime([\"2026-01-01\",\"2026-01-03\"]))\nprint(s.asfreq(\"D\"))", "check": "Enero 2 queda como NaN.", "hint": "Usa asfreq(\"D\").", "explanation": "Enero 2 queda como NaN."}, {"title": "Promedio sin futuro", "prompt": "Calcula la media de dos observaciones anteriores para [10,20,30,40].", "solution": "import pandas as pd\ns=pd.Series([10,20,30,40])\nprint(s.shift(1).rolling(2,min_periods=2).mean())", "check": "NaN, NaN, 15, 25.", "hint": "Desplaza antes de la ventana.", "explanation": "NaN, NaN, 15, 25."}], "quiz": [{"question": "¿Qué hace resample?", "options": ["Agrupa por intervalos temporales para agregar", "Solo renombra columnas", "Siempre interpola"], "answer": 0, "explanation": "Debes elegir la agregación adecuada."}, {"question": "¿rolling(3) siempre equivale a 3 días?", "options": ["Sí", "No", "Solo en NumPy"], "answer": 1, "explanation": "Cuenta observaciones; necesita una frecuencia diaria regular para equivaler."}, {"question": "¿Qué evita usar el dato actual en una media predictora?", "options": ["shift(1) antes de rolling", "center=True", "Ordenar de mayor a menor"], "answer": 0, "explanation": "El rezago separa la información previa del valor que se pretende predecir."}], "homework": {"title": "Laboratorio · Series de tiempo", "context": "Ordena fechas, distingue frecuencia de agregación y calcula indicadores temporales sin mirar el futuro.", "steps": ["Genera 10 días con ingresos y elimina un día deliberadamente.", "Compara asfreq diario y resample semanal; declara cómo tratas huecos.", "Calcula media móvil de tres observaciones, media de tres días y acumulada.", "Grafica y explica diferencias, cobertura y riesgo de fuga de información."]}, "id": 11, "badge": 2, "phase": "Badge 2 · Analista con Pandas"}, {"id": 12, "title": "Entiende lo que resumen los números", "short": "Estadística descriptiva", "phase": "Badge 2 · Analista con Pandas", "description": "Elige medidas útiles y reconoce lo que una muestra puede y no puede decir.", "objectives": ["Comparar media y mediana.", "Interpretar dispersión y cuantiles.", "Distinguir asociación de causalidad."], "lessons": [{"title": "Centro: media y mediana", "text": ["La media reparte el total por igual entre observaciones. La mediana es el valor central después de ordenar. Responden a preguntas distintas y reaccionan de forma diferente a extremos.", "En ingresos [100, 100, 100, 100, 1000], la media supera la mayoría de observaciones. Mostrar también mediana y distribución evita describir mal el caso típico."], "code": "import pandas as pd\n\ningresos = pd.Series([100, 100, 100, 100, 1000])\nprint(\"Media:\", ingresos.mean())\nprint(\"Mediana:\", ingresos.median())\nprint(\"Total:\", ingresos.sum())", "output": "Media 280.0; mediana 100.0; total 1400.", "tip": "Una medida no es mejor en todos los casos. Decide según la pregunta y explica qué representa."}, {"title": "Dispersión y cuantiles", "text": ["Dos grupos pueden tener la misma media y variaciones muy distintas. El rango compara extremos; la desviación estándar resume distancias respecto a la media en las mismas unidades.", "Los cuantiles describen posiciones en la distribución. El rango intercuartílico, Q3 − Q1, resume la amplitud del 50 % central. Aquí usamos ddof=0 para describir el conjunto completo del ejemplo."], "code": "import pandas as pd\n\na = pd.Series([10, 10, 10])\nb = pd.Series([0, 10, 20])\nprint(a.mean(), b.mean())\nprint(a.std(ddof=0), round(b.std(ddof=0), 2))\nprint(b.quantile([0.25, 0.5, 0.75]))", "output": "Ambas medias son 10.0; desviaciones 0.0 y 8.16. Cuantiles: 5, 10 y 15.", "tip": "Pandas usa ddof=1 por defecto para std; especifica la convención cuando sea importante para interpretar o comparar resultados."}, {"title": "Asociación, muestras y límites", "text": ["La correlación de Pearson describe asociación lineal entre variables numéricas. No prueba que una cause a la otra y puede cambiar por extremos o grupos mezclados.", "Un conjunto de datos representa las observaciones que se recogieron. Si solo analizas clientes de una sucursal, no puedes asegurar que las conclusiones describan a todo el país."], "code": "import pandas as pd\n\ndatos = pd.DataFrame({\"Publicidad\": [1, 2, 3, 4], \"Ventas\": [10, 20, 30, 40]})\nprint(datos.corr())", "output": "La correlación entre ambas columnas es 1.0 en este ejemplo construido.", "tip": "La asociación perfecta de cuatro datos artificiales no demuestra un efecto causal de publicidad sobre ventas."}], "tasks": [{"title": "¿Qué es típico?", "prompt": "Calcula media y mediana de [10, 12, 13, 15, 100]. Explica la diferencia.", "check": "Media 30.0; mediana 13.0.", "hint": "Ordena mentalmente los valores y observa el extremo.", "solution": "import pandas as pd\ns = pd.Series([10, 12, 13, 15, 100])\nprint(s.mean(), s.median())", "explanation": "El 100 eleva la media, mientras la posición central sigue siendo 13."}, {"title": "Misma media, distinta variación", "prompt": "Compara [5, 5, 5] y [1, 5, 9] con media y rango.", "check": "Medias 5; rangos 0 y 8.", "hint": "Rango = máximo − mínimo.", "solution": "import pandas as pd\nfor valores in [[5, 5, 5], [1, 5, 9]]:\n    s = pd.Series(valores)\n    print(\"Media:\", s.mean(), \"Rango:\", s.max() - s.min())", "explanation": "La igualdad de medias no implica distribuciones iguales."}], "quiz": [{"question": "¿Qué medida es más sensible a un extremo grande?", "options": ["Media", "Mediana", "Número de columnas"], "answer": 0, "explanation": "La media usa la magnitud de todos los valores."}, {"question": "¿Correlación implica causalidad?", "options": ["Sí", "No", "Solo si es positiva"], "answer": 1, "explanation": "Puede haber variables de confusión, selección o coincidencia."}, {"question": "¿Por qué informar la cantidad de observaciones?", "options": ["Para contextualizar el resumen", "Para eliminar la incertidumbre", "Para demostrar representatividad por sí sola"], "answer": 0, "explanation": "El tamaño da contexto, pero no garantiza representatividad ni calidad."}], "homework": {"title": "Un resumen que no engañe", "context": "Usa ingresos [1200, 1500, 1600, 1700, 1800, 9000].", "steps": ["Calcula tamaño, media, mediana, mínimo y máximo.", "Calcula Q1, Q3 y rango intercuartílico.", "Compara media y mediana con una explicación contextual.", "Escribe una limitación de concluir a partir de solo seis observaciones."]}, "badge": 2}, {"id": 13, "title": "De los datos a una conclusión", "short": "Análisis reproducible", "phase": "Badge 2 · Analista con Pandas", "description": "Construye una historia verificable: pregunta, evidencia, interpretación y límites.", "objectives": ["Diseñar un análisis exploratorio.", "Validar indicadores y comunicar límites.", "Preparar la entrega del proyecto."], "lessons": [{"title": "Una pregunta que los datos puedan responder", "text": ["El análisis exploratorio combina inspección, resúmenes y gráficos. Comienza con una pregunta acotada: ¿qué producto generó mayor ingreso registrado durante el período disponible?", "Define la unidad de observación, el período y las exclusiones. Distingue una pregunta descriptiva de una causal: comparar ingresos no demuestra por qué cambiaron."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"Producto\": [\"A\", \"B\", \"A\"], \"Precio\": [100, 200, 100], \"Cantidad\": [2, 1, 3]})\nventas[\"Ingreso\"] = ventas[\"Precio\"] * ventas[\"Cantidad\"]\nresumen = ventas.groupby(\"Producto\")[\"Ingreso\"].sum().sort_values(ascending=False)\nprint(resumen)\nprint(\"Total:\", resumen.sum())", "output": "A genera 500 y B genera 200; el total registrado es 700.", "tip": "Describe el universo observado: “en estos registros”, no “en todo el mercado”."}, {"title": "Validar para confiar en la conclusión", "text": ["Una validación comprueba una expectativa explícita. assert detiene la ejecución si no se cumple. Es útil para verificar claves, cantidades no negativas o conservación de totales.", "Las reglas deben corresponder al contexto. Si el negocio acepta devoluciones, no puedes exigir que todas las cantidades sean positivas sin separar esos casos."], "code": "import pandas as pd\n\nventas = pd.DataFrame({\"id\": [1, 2, 3], \"Producto\": [\"A\", \"B\", \"A\"], \"Ingreso\": [200, 200, 300]})\nassert ventas[\"id\"].is_unique\nassert ventas[\"Ingreso\"].notna().all()\nresumen = ventas.groupby(\"Producto\")[\"Ingreso\"].sum()\nassert abs(resumen.sum() - ventas[\"Ingreso\"].sum()) < 0.01\nprint(\"Controles aprobados\")", "output": "Controles aprobados.", "tip": "Un control aprobado confirma esa regla específica; no garantiza que todos los datos sean correctos."}, {"title": "Comunicar y preparar el siguiente paso", "text": ["Una conclusión útil reúne hallazgo, evidencia y alcance. Por ejemplo: “A aporta 500 de 700 unidades monetarias registradas (71.4 %); el conjunto solo contiene tres ventas”.", "Un notebook final incluye objetivo, fuente, diccionario, limpieza, análisis, gráficos, conclusiones y limitaciones. Para aprender modelos después, habrá que separar entrenamiento y prueba, evitar fuga de información y comparar con una referencia sencilla."], "code": "ingreso_a = 500\ningreso_total = 700\nparticipacion = ingreso_a / ingreso_total * 100\nprint(f\"A aporta {participacion:.1f}% del ingreso registrado.\")\nprint(\"Límite: solo se observaron tres registros de venta.\")", "output": "A aporta 71.4% del ingreso registrado. Se declara el límite de la muestra.", "tip": "La calidad de una conclusión depende de la evidencia y de reconocer lo que todavía no sabes."}], "tasks": [{"title": "Una conclusión verificable", "prompt": "Con ingresos A: 300 y B: 100, calcula la participación de A y redacta una conclusión limitada al conjunto.", "check": "75 %.", "hint": "Divide el ingreso de A entre el total.", "solution": "ingresos = {\"A\": 300, \"B\": 100}\nporcentaje = ingresos[\"A\"] / sum(ingresos.values()) * 100\nprint(f\"A representa {porcentaje:.0f}% del ingreso observado.\")", "explanation": "La participación describe el conjunto disponible, no el mercado completo."}, {"title": "Comprueba conservación", "prompt": "Agrupa X, X, Y con ingresos 10, 15 y 25. Verifica que el total no cambie.", "check": "Ambos totales son 50.", "hint": "Compara la suma antes y después de groupby.", "solution": "import pandas as pd\ndf = pd.DataFrame({\"Producto\": [\"X\", \"X\", \"Y\"], \"Ingreso\": [10, 15, 25]})\nr = df.groupby(\"Producto\")[\"Ingreso\"].sum()\nassert r.sum() == df[\"Ingreso\"].sum()\nprint(r.sum())", "explanation": "La agrupación redistribuye registros en grupos, pero conserva la suma en este conjunto sin claves faltantes."}], "quiz": [{"question": "¿Qué debe acompañar a un hallazgo?", "options": ["Evidencia y alcance", "Solo una opinión", "Una promesa de causalidad"], "answer": 0, "explanation": "La conclusión debe mostrar en qué datos se apoya y a qué observaciones aplica."}, {"question": "¿Qué demuestra un assert aprobado?", "options": ["Que esa condición se cumplió", "Que no existe ningún error posible", "Que la muestra representa a todos"], "answer": 0, "explanation": "Cada control tiene un alcance concreto."}, {"question": "¿Cuándo separar entrenamiento y prueba?", "options": ["Antes de ajustar transformaciones y modelos", "Después de usar todos los datos para entrenar", "Nunca"], "answer": 0, "explanation": "En una extensión de modelos, separar antes ayuda a evitar que información de prueba influya en el entrenamiento."}], "homework": {"title": "Primera versión del proyecto", "context": "Usa los archivos sintéticos del proyecto y la guía de la sección Proyecto final.", "steps": ["Formula tres preguntas respondibles con los archivos disponibles.", "Entrega un informe de calidad y una tabla analítica validada.", "Incluye tablas de resultados y conclusiones con cifras; desarrolla los gráficos en el badge 4.", "Reinicia y ejecuta el notebook completo; documenta exclusiones y limitaciones."]}, "badge": 2}, {"id": 14, "title": "Calcula con colecciones numéricas", "short": "NumPy esencial", "phase": "Badge 3 · Cálculo avanzado con NumPy", "description": "Realiza operaciones sobre arreglos y comprende sus dimensiones.", "objectives": ["Distinguir listas de arreglos.", "Aplicar operaciones vectorizadas.", "Reconocer dimensiones y aleatoriedad reproducible."], "lessons": [{"title": "De una lista a un arreglo", "text": ["Un arreglo de NumPy organiza valores de un tipo compatible y permite operaciones numéricas sobre todos sus elementos. Multiplicar una lista por dos repite sus elementos; multiplicar un arreglo por dos duplica cada valor.", "La vectorización expresa una operación para el conjunto, sin escribir un ciclo explícito. Esto facilita leer la intención del cálculo."], "code": "import numpy as np\n\nlista = [2, 4, 6]\narreglo = np.array(lista)\nprint(lista * 2)\nprint(arreglo * 2)\nprint(arreglo.mean())", "output": "La lista se repite: [2, 4, 6, 2, 4, 6]. El arreglo produce [4, 8, 12]. Su media es 4.0.", "tip": "No asumas que dos objetos responden igual al mismo operador: revisa su tipo."}, {"title": "Forma, posiciones y ejes", "text": ["shape indica cuántos elementos hay en cada dimensión. Una matriz de 2 × 3 tiene dos filas y tres columnas. El acceso [fila, columna] usa posiciones desde cero.", "En una tabla bidimensional, sum(axis=0) suma a través de las filas y devuelve un total por columna. sum(axis=1) suma las columnas y devuelve un total por fila."], "code": "import numpy as np\n\nmatriz = np.array([[2, 4, 6], [1, 3, 5]])\nprint(matriz.shape)\nprint(matriz[1, 0])\nprint(matriz.sum(axis=0))\nprint(matriz.sum(axis=1))", "output": "(2, 3); 1; [3, 7, 11]; [12, 9].", "tip": "Describe la salida con palabras antes de elegir el eje: ¿necesitas un resultado por fila o por columna?"}, {"title": "Máscaras y datos de simulación", "text": ["Una comparación sobre un arreglo produce valores booleanos. Se pueden usar como máscara para conservar elementos que cumplen una condición.", "Un generador con semilla permite repetir una simulación en el mismo entorno. No convierte los datos simulados en evidencia del mundo real. El límite superior de integers es exclusivo."], "code": "import numpy as np\n\nprecios = np.array([500, 1500, 600, 1200])\nprint(precios[precios > 700])\nrng = np.random.default_rng(42)\nsimulacion = rng.integers(1, 6, size=5)\nprint(simulacion)\nprint(np.all((simulacion >= 1) & (simulacion <= 5)))", "output": "El filtro devuelve [1500, 1200]. La simulación contiene cinco enteros entre 1 y 5; la comprobación es True.", "tip": "Fija la semilla y registra las versiones si necesitas reproducir una simulación con precisión."}], "tasks": [{"title": "Ingresos vectorizados", "prompt": "Crea precios [1500, 500, 600] y cantidades [4, 10, 2] como arreglos. Calcula ingresos y total.", "check": "[6000, 5000, 1200] y total 12200.", "hint": "Multiplica arreglos de igual forma.", "solution": "import numpy as np\np = np.array([1500, 500, 600])\nc = np.array([4, 10, 2])\ningresos = p * c\nprint(ingresos)\nprint(ingresos.sum())", "explanation": "Cada precio se multiplica por la cantidad en la misma posición."}, {"title": "Filtra temperaturas", "prompt": "De [18, 22, 25, 19, 28], conserva las temperaturas >= 22 y calcula su media.", "check": "[22, 25, 28] y media 25.0.", "hint": "Primero crea una máscara, luego usa mean.", "solution": "import numpy as np\nt = np.array([18, 22, 25, 19, 28])\nseleccion = t[t >= 22]\nprint(seleccion)\nprint(seleccion.mean())", "explanation": "La media se calcula solo sobre los valores seleccionados."}], "quiz": [{"question": "¿Qué produce np.array([1, 2]) * 2?", "options": ["[1, 2, 1, 2]", "[2, 4]", "[3, 4]"], "answer": 1, "explanation": "La multiplicación es elemento por elemento."}, {"question": "¿Qué significa shape = (2, 3)?", "options": ["Dos filas y tres columnas", "Tres filas y dos columnas", "Cinco dimensiones"], "answer": 0, "explanation": "La primera dimensión describe filas en esta matriz."}, {"question": "¿Para qué sirve una semilla?", "options": ["Garantizar datos reales", "Repetir una secuencia pseudoaleatoria en el mismo entorno", "Evitar toda incertidumbre"], "answer": 1, "explanation": "La semilla ayuda a reproducir una simulación; no valida sus supuestos."}], "homework": {"title": "Semana de temperaturas", "context": "Usa [21, 23, 22, 24, 25, 20, 19] como temperaturas diarias en °C.", "steps": ["Crea un arreglo y muestra su forma.", "Calcula mínimo, máximo y media.", "Selecciona los días con temperatura mayor que 22.", "Explica por qué filtrar modifica el conjunto sobre el cual se calcula la media."]}, "badge": 3}, {"title": "Matrices y álgebra lineal aplicada", "short": "Matrices y broadcasting", "description": "Domina dimensiones, productos matriciales y sistemas lineales con arreglos de NumPy.", "objectives": ["Distinguir * y @.", "Aplicar broadcasting por ejes.", "Resolver un sistema y comprobar su residuo."], "lessons": [{"title": "Forma, transposición y producto", "text": ["Usa ndarray bidimensional para matrices. * multiplica elemento por elemento; @ realiza producto matricial. Para A de forma (m,n) y B de forma (n,p), A @ B tiene forma (m,p).", "reshape reorganiza una cantidad compatible de elementos; .T transpone ejes en una matriz. Una transposición puede ser una vista de los mismos datos: usa copy si necesitas independencia."], "code": "import numpy as np\nA=np.array([[1,2],[3,4]])\nB=np.array([[2,0],[0,2]])\nprint(A*B)\nprint(A@B)\nprint(A.T)", "output": "Elemento a elemento: [[2,0],[0,8]]. Matricial: [[2,4],[6,8]].", "tip": "Comprueba shapes antes de operar. No necesitas np.matrix."}, {"title": "Broadcasting: compatibilidad, no magia", "text": ["NumPy compara dimensiones desde la derecha: deben coincidir o una debe ser 1. Una media por columna con keepdims=True tiene forma (1,n) y puede restarse de una matriz (m,n).", "Para estandarizar, resta media y divide por desviación. Una columna constante tiene desviación cero: define una política antes de dividir. En modelado, ajusta estas estadísticas solo con entrenamiento."], "code": "import numpy as np\nX=np.array([[1.,10.],[3.,20.],[5.,30.]])\nmedia=X.mean(axis=0,keepdims=True)\nescala=X.std(axis=0,keepdims=True)\nZ=(X-media)/np.where(escala==0,1,escala)\nprint(media.shape)\nprint(np.round(Z.mean(axis=0),6))", "output": "La media tiene forma (1,2); las medias estandarizadas son [0,0].", "tip": "Broadcasting no implica que las dimensiones tengan significado compatible: verifica unidades y ejes."}, {"title": "Resolver y verificar", "text": ["np.linalg.solve encuentra x para A @ x = b si A es cuadrada y de rango completo. Evita calcular la inversa explícitamente solo para resolver el sistema.", "Un residuo pequeño confirma que la solución satisface aproximadamente la ecuación. Un sistema mal condicionado puede amplificar errores; revisa cond y considera el contexto. Para un sistema rectangular se estudia lstsq como extensión."], "code": "import numpy as np\nA=np.array([[2.,1.],[1.,3.]])\nb=np.array([5.,10.])\nx=np.linalg.solve(A,b)\nprint(x)\nprint(np.allclose(A@x,b))\nprint(np.linalg.norm(A@x-b))", "output": "x=[1,3]; verificación True; residuo cercano a cero.", "tip": "Un residuo pequeño no elimina por sí solo problemas de condicionamiento."}], "tasks": [{"title": "Ingresos con una matriz", "prompt": "Filas de cantidades [[2,3],[1,4]] y precios [10,20]. Calcula ingreso por fila.", "solution": "import numpy as np\nQ=np.array([[2,3],[1,4]])\np=np.array([10,20])\nprint(Q@p)", "check": "[80,90].", "hint": "Usa @, no *.", "explanation": "[80,90]."}, {"title": "Centra por columna", "prompt": "Centra [[1,10],[3,20]] restando su media por columna.", "solution": "import numpy as np\nX=np.array([[1.,10.],[3.,20.]])\nprint(X-X.mean(axis=0,keepdims=True))", "check": "[[-1,-5],[1,5]].", "hint": "axis=0 reduce filas.", "explanation": "[[-1,-5],[1,5]]."}], "quiz": [{"question": "¿Qué operador hace producto matricial?", "options": ["*", "@", "&"], "answer": 1, "explanation": "@ contrae la dimensión compartida."}, {"question": "¿Qué dimensiones son compatibles al comparar desde la derecha?", "options": ["Iguales o una de tamaño 1", "Cualquier par", "Solo matrices cuadradas"], "answer": 0, "explanation": "Esa es la regla básica de broadcasting."}, {"question": "¿Cómo resolver A@x=b?", "options": ["solve(A,b)", "A*b siempre", "Ordenar b"], "answer": 0, "explanation": "solve resuelve un sistema cuadrado no singular."}], "homework": {"title": "Laboratorio · Matrices y broadcasting", "context": "Domina dimensiones, productos matriciales y sistemas lineales con arreglos de NumPy.", "steps": ["Crea cantidades de tres sucursales por dos productos y calcula ingreso con @.", "Estandariza por columna, explicando eje y tratamiento de constantes.", "Resuelve un sistema 2×2 y mide el residuo.", "Incluye un ejemplo de formas incompatibles y explica cómo corregir el diseño."]}, "id": 15, "badge": 3, "phase": "Badge 3 · Cálculo avanzado con NumPy"}, {"title": "Datos inválidos sin perder la forma", "short": "Máscaras y masked arrays", "description": "Distingue selección booleana, valores NaN y máscaras persistentes.", "objectives": ["Seleccionar con máscaras booleanas.", "Excluir inválidos con numpy.ma.", "Medir cobertura válida por eje."], "lessons": [{"title": "Máscara booleana: True selecciona", "text": ["Una comparación produce un arreglo booleano. x[mask] conserva valores donde la máscara es True; al seleccionar de una matriz puede devolver un vector y perder la organización original.", "np.where permite elegir entre alternativas conservando una forma compatible. Para detectar valores finitos usa np.isfinite, que excluye NaN e infinito."], "code": "import numpy as np\nx=np.array([[1.,np.nan],[3.,np.inf]])\nvalido=np.isfinite(x)\nprint(x[valido])\nprint(np.where(valido,x,0))", "output": "Selección: [1,3]. where conserva 2×2 sustituyendo inválidos por 0 en esta demostración.", "tip": "Sustituir por cero cambia estadísticas. No lo uses como limpieza automática."}, {"title": "MaskedArray: True excluye", "text": ["numpy.ma combina valores y una máscara, manteniendo dimensiones. A diferencia de la selección booleana, True en la máscara significa que el valor está excluido. Sus reducciones ignoran los valores enmascarados.", "masked_invalid enmascara NaN e infinitos. También puedes definir reglas de dominio, por ejemplo temperaturas de sensor fuera de rango. La máscara expresa tu decisión y no inventa mediciones."], "code": "import numpy as np\nx=np.array([10.,20.,-999.,30.])\nm=np.ma.masked_where(x==-999,x)\nprint(m)\nprint(m.mean())\nprint(m.count())", "output": "Valor -999 enmascarado; media 20.0; conteo válido 3.", "tip": "Recuerda la inversión: True selecciona en x[mask], pero True excluye en numpy.ma."}, {"title": "Cobertura y grupos totalmente inválidos", "text": ["count informa cuántos valores válidos quedan por eje. Un grupo sin datos válidos debe mantenerse como desconocido; reportar cero sería engañoso.", "filled convierte la máscara a un valor de relleno. Con floats puedes usar NaN para exportar. Documenta las reglas y conserva el conteo de válidos junto a cualquier promedio."], "code": "import numpy as np\nx=np.array([[10.,np.nan],[20.,np.inf]])\nm=np.ma.masked_invalid(x)\nprint(m.count(axis=0))\nprint(m.mean(axis=0))\nprint(m.mean(axis=0).filled(np.nan))", "output": "Conteos [2,0]; medias [15,enmascarado]; al exportar [15,NaN].", "tip": "Una media sin cobertura puede ocultar que todos los datos del grupo son inválidos."}], "tasks": [{"title": "Excluye el código del sensor", "prompt": "Enmascara -999 en [5, -999, 15] y calcula media y conteo.", "solution": "import numpy as np\nx=np.array([5.,-999.,15.])\nm=np.ma.masked_where(x==-999,x)\nprint(m.mean(),m.count())", "check": "Media 10; conteo 2.", "hint": "El código -999 no es una medición.", "explanation": "Media 10; conteo 2."}, {"title": "Una columna sin datos", "prompt": "Para [[1,NaN],[3,NaN]], calcula media válida por columna.", "solution": "import numpy as np\nx=np.array([[1.,np.nan],[3.,np.nan]])\nm=np.ma.masked_invalid(x)\nprint(m.mean(axis=0).filled(np.nan))\nprint(m.count(axis=0))", "check": "[2,NaN] y conteos [2,0].", "hint": "Usa masked_invalid y filled.", "explanation": "[2,NaN] y conteos [2,0]."}], "quiz": [{"question": "True en numpy.ma.mask significa…", "options": ["Excluir el valor", "Seleccionarlo como válido", "Convertirlo a 1"], "answer": 0, "explanation": "La máscara identifica datos que no participan."}, {"question": "¿Qué hace x[mask] con True?", "options": ["Conserva ese valor", "Lo excluye", "Siempre rellena cero"], "answer": 0, "explanation": "La selección booleana usa la convención contraria a la máscara de numpy.ma."}, {"question": "¿Cómo reportar una columna sin observaciones válidas?", "options": ["Media 0", "Desconocida y conteo 0", "Media 1"], "answer": 1, "explanation": "No hay evidencia para estimar su media."}], "homework": {"title": "Laboratorio · Máscaras y masked arrays", "context": "Distingue selección booleana, valores NaN y máscaras persistentes.", "steps": ["Simula 4 días × 3 sensores con NaN, infinito y -999.", "Define explícitamente qué códigos son inválidos.", "Calcula medias y conteos válidos por sensor y por día.", "Exporta con NaN y explica por qué los inválidos no se reemplazan por cero."]}, "id": 16, "badge": 3, "phase": "Badge 3 · Cálculo avanzado con NumPy"}, {"title": "Ventanas para señales y secuencias", "short": "Window functions", "description": "Calcula indicadores móviles y distingue una ventana de observaciones de una ponderación de señal.", "objectives": ["Construir ventanas con sliding_window_view.", "Calcular medias móviles y ponderadas.", "Definir bordes, alineación y costo."], "lessons": [{"title": "Ventanas deslizantes sin ciclos explícitos", "text": ["sliding_window_view crea una vista de ventanas superpuestas. Para N observaciones y ancho W, obtienes N−W+1 ventanas completas. Cada fila contiene W observaciones contiguas.", "La vista comparte memoria y es de solo lectura por defecto. Evita escribir en ventanas superpuestas. Aunque crear la vista puede ser barato, reducir todas las ventanas cuesta aproximadamente O(N×W)."], "code": "import numpy as np\nfrom numpy.lib.stride_tricks import sliding_window_view\nx=np.array([10.,20.,30.,40.,50.])\nw=sliding_window_view(x,3)\nprint(w)\nprint(w.mean(axis=-1))", "output": "Ventanas [10,20,30], [20,30,40], [30,40,50]; medias [20,30,40].", "tip": "Estas ventanas usan posiciones, no fechas. Si el tiempo es irregular, vuelve a definir la frecuencia o usa Pandas."}, {"title": "Pesos, convolución y significado de window", "text": ["Una media ponderada necesita pesos con suma positiva; normalízalos para sumar uno. Aquí el peso mayor corresponde a la observación más reciente y la salida se alinea al final de cada ventana.", "np.convolve con mode=\"valid\" produce solo posiciones con solapamiento completo. Para pesos asimétricos, la convolución invierte el núcleo. Las ventanas Hann o Hamming son ponderaciones de señal, no operaciones rolling por sí solas."], "code": "import numpy as np\nfrom numpy.lib.stride_tricks import sliding_window_view\nx=np.array([10.,20.,30.,40.,50.])\npesos=np.array([1.,2.,3.]); pesos=pesos/pesos.sum()\ny=sliding_window_view(x,3)@pesos\nprint(np.round(y,2))\nprint(np.allclose(y,np.convolve(x,pesos[::-1],mode=\"valid\")))\nprint(np.hanning(5))", "output": "Medias [23.33,33.33,43.33]; equivalencia True. Hann de 5: [0,0.5,1,0.5,0].", "tip": "No confundas una función de ponderación con una ventana de observaciones: pueden combinarse, pero cumplen papeles distintos."}, {"title": "Bordes, alineación y cálculo eficiente", "text": ["Una media móvil de ancho 3 no está definida para las primeras dos posiciones si exiges una ventana completa. Puedes alinear las salidas con el final de cada ventana y conservar NaN al principio.", "Para datos finitos, una suma acumulada permite calcular sumas móviles en O(N). Con NaN este atajo requiere sumas y conteos separados. Para predecir el valor actual, desplaza antes: una ventana que incluye el presente no es una variable exclusivamente pasada."], "code": "import numpy as np\nx=np.array([10.,20.,30.,40.,50.])\nk=3\ns=np.r_[0.,np.cumsum(x)]\nmedias=(s[k:]-s[:-k])/k\nalineada=np.r_[np.full(k-1,np.nan),medias]\nprint(alineada)", "output": "[NaN,NaN,20,30,40].", "tip": "Documenta ancho, mínimo de válidos, alineación y política de bordes antes de comparar resultados."}], "tasks": [{"title": "Media de ancho dos", "prompt": "Calcula ventanas completas de [2,4,6,8] con ancho 2.", "solution": "import numpy as np\nfrom numpy.lib.stride_tricks import sliding_window_view\nx=np.array([2.,4.,6.,8.])\nprint(sliding_window_view(x,2).mean(axis=-1))", "check": "[3,5,7].", "hint": "Reduce el último eje.", "explanation": "[3,5,7]."}, {"title": "Pesos con prioridad reciente", "prompt": "Usa pesos [1,3] normalizados sobre [2,4,6,8].", "solution": "import numpy as np\nfrom numpy.lib.stride_tricks import sliding_window_view\nx=np.array([2.,4.,6.,8.]);p=np.array([1.,3.]);p=p/p.sum()\nprint(sliding_window_view(x,2)@p)", "check": "[3.5,5.5,7.5].", "hint": "El último peso corresponde al dato reciente.", "explanation": "[3.5,5.5,7.5]."}], "quiz": [{"question": "¿Cuántas ventanas completas produce N=10, W=3?", "options": ["10", "8", "3"], "answer": 1, "explanation": "N−W+1 = 8."}, {"question": "¿Una vista hace gratuita toda reducción?", "options": ["Sí", "No", "Solo si tiene NaN"], "answer": 1, "explanation": "Procesar N ventanas de ancho W puede requerir O(N×W)."}, {"question": "¿Qué es np.hanning?", "options": ["Una secuencia de pesos", "Un índice de fechas", "Una unión de tablas"], "answer": 0, "explanation": "Genera ponderaciones; no desplaza ventanas de datos automáticamente."}], "homework": {"title": "Laboratorio · Window functions", "context": "Calcula indicadores móviles y distingue una ventana de observaciones de una ponderación de señal.", "steps": ["Genera 30 observaciones con semilla fija y una anomalía intencional.", "Compara medias móviles simples y ponderadas con anchos 3 y 5.", "Verifica una media con suma acumulada; documenta bordes y alineación.", "Integra una máscara de inválidos e informa conteos mínimos y limitaciones."]}, "id": 17, "badge": 3, "phase": "Badge 3 · Cálculo avanzado con NumPy"}, {"id": 18, "title": "Haz visibles tus hallazgos", "short": "Visualización", "phase": "Badge 4 · Visualización y narrativa de datos", "description": "Construye gráficos que respondan preguntas y se puedan leer sin explicación adicional.", "objectives": ["Elegir un gráfico según la pregunta.", "Crear gráficos con Matplotlib.", "Etiquetar unidades y evitar comparaciones engañosas."], "lessons": [{"title": "Comparar categorías con barras", "text": ["Un gráfico de barras compara magnitudes entre categorías. Ordenar valores facilita encontrar máximos y mínimos. Un eje que parte de cero evita exagerar diferencias de longitud.", "Un título útil expresa el contenido y período. Las etiquetas deben incluir unidades. No dependas solo del color para distinguir información."], "code": "import matplotlib.pyplot as plt\n\nproductos = [\"Regla\", \"Lapicero\", \"Cuaderno\"]\ningresos = [1200, 5000, 6000]\nfig, ax = plt.subplots(figsize=(7, 4))\nax.barh(productos, ingresos, color=\"#216556\")\nax.set(title=\"Ingresos de la venta de práctica\", xlabel=\"Ingreso (CRC)\")\nax.set_xlim(left=0)\nfig.tight_layout()\nplt.show()", "output": "Cuaderno tiene la barra más larga (₡6000) y Regla la más corta (₡1200).", "tip": "El gráfico muestra ingreso, no ganancia. Usa nombres precisos para el indicador.", "image": "graficos/sesion_18_1.png"}, {"title": "Distribuciones y relaciones", "text": ["Un histograma agrupa una variable numérica en intervalos para observar su distribución. El número de intervalos afecta la apariencia; prueba opciones razonables e informa el tamaño de la muestra.", "Un diagrama de dispersión representa pares de valores. Sirve para explorar relaciones, grupos y observaciones inusuales. Cada punto debe tener un significado claro."], "code": "import matplotlib.pyplot as plt\n\ncantidades = [1, 1, 2, 2, 2, 3, 4, 5, 8]\nfig, ax = plt.subplots(figsize=(7, 4))\nax.hist(cantidades, bins=[0.5, 2.5, 4.5, 6.5, 8.5], color=\"#7155ba\", edgecolor=\"white\")\nax.set(title=\"Unidades por registro (n=9)\", xlabel=\"Unidades\", ylabel=\"Registros\")\nfig.tight_layout()\nplt.show()", "output": "Los intervalos contienen 5, 2, 1 y 1 registros respectivamente.", "tip": "Una frecuencia cuenta observaciones; no es automáticamente porcentaje ni densidad.", "image": "graficos/sesion_18_2.png"}, {"title": "Tiempo y exportación legible", "text": ["Un gráfico de líneas es útil cuando el orden temporal tiene sentido. Ordena las fechas y evita tratar categorías arbitrarias como una serie temporal.", "Exporta con suficiente resolución y revisa que títulos y etiquetas no estén cortados. Incluye la fuente o explica si son datos de práctica."], "code": "import pandas as pd\nimport matplotlib.pyplot as plt\n\nfechas = pd.to_datetime([\"2026-01-01\", \"2026-01-02\", \"2026-01-03\"])\nfig, ax = plt.subplots(figsize=(7, 4))\nax.plot(fechas, [99, 216, 102], marker=\"o\", color=\"#216556\")\nax.set(title=\"Ingresos diarios · ejemplo didáctico\", xlabel=\"Fecha\", ylabel=\"Ingreso (unidades monetarias)\")\nfig.autofmt_xdate()\nfig.tight_layout()\nfig.savefig(\"ingresos_diarios.png\", dpi=150, bbox_inches=\"tight\")\nplt.show()", "output": "El segundo día tiene el ingreso más alto. Se guarda ingresos_diarios.png.", "tip": "Tres días no bastan para afirmar una tendencia estable ni un patrón estacional.", "image": "graficos/sesion_18_3.png"}], "tasks": [{"title": "Categorías legibles", "prompt": "Grafica en barras A: 30, B: 50 y C: 20 unidades. Incluye título y nombre del eje.", "check": "B aparece como la mayor categoría; el eje indica unidades.", "hint": "Usa ax.bar.", "solution": "import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.bar([\"A\", \"B\", \"C\"], [30, 50, 20], color=\"#216556\")\nax.set(title=\"Unidades por producto\", ylabel=\"Unidades\")\nfig.tight_layout()\nplt.show()", "explanation": "Las barras parten de cero y comparan la misma unidad."}, {"title": "Dos variables", "prompt": "Crea un gráfico de dispersión con precios [10, 20, 30, 40] y cantidades [8, 6, 5, 2].", "check": "Cuatro puntos; etiquetas Precio y Cantidad.", "hint": "Usa ax.scatter y evita una conclusión causal.", "solution": "import matplotlib.pyplot as plt\nfig, ax = plt.subplots()\nax.scatter([10, 20, 30, 40], [8, 6, 5, 2], color=\"#7155ba\")\nax.set(title=\"Precio y cantidad · datos de práctica\", xlabel=\"Precio\", ylabel=\"Cantidad\")\nfig.tight_layout()\nplt.show()", "explanation": "Hay una asociación descendente en estos cuatro puntos; no demuestra que bajar precios cause mayores ventas."}], "quiz": [{"question": "¿Qué gráfico compara categorías?", "options": ["Barras", "Líneas temporales siempre", "Ninguno"], "answer": 0, "explanation": "Las barras permiten comparar magnitudes entre categorías."}, {"question": "¿Qué necesita una etiqueta de eje?", "options": ["Solo un color", "El nombre de la variable y su unidad cuando corresponda", "Una conclusión causal"], "answer": 1, "explanation": "Una etiqueta clara permite interpretar la escala."}, {"question": "¿Qué importa antes de dibujar una línea temporal?", "options": ["Ordenar las fechas", "Ordenar alfabéticamente los ingresos", "Eliminar las fechas"], "answer": 0, "explanation": "El orden temporal define cómo se conectan las observaciones."}], "homework": {"title": "Tres vistas de ventas", "context": "Usa ventas.csv y crea Ingreso.", "steps": ["Crea barras con ingreso total por producto.", "Crea un gráfico de líneas con ingreso total por fecha.", "Crea dispersión Precio frente a Cantidad y explica su limitación con cinco registros.", "Exporta los gráficos e incluye una conclusión por gráfico."]}, "badge": 4}, {"title": "Matplotlib: controla cada elemento", "short": "Matplotlib aplicado", "description": "Diseña figuras compuestas, anota hallazgos y exporta gráficos legibles.", "objectives": ["Distinguir Figure y Axes.", "Construir paneles con escalas coherentes.", "Exportar PNG y SVG sin recortes."], "lessons": [{"title": "Figure, Axes y paneles con propósito", "text": ["Figure es el lienzo completo y cada Axes es una región de trazado. Crear ambos explícitamente facilita combinar gráficos y modificar un eje sin alterar otros.", "Un panel debe responder a una pregunta. Aquí comparamos volumen e ingreso por producto. No compartimos el eje de valores porque las unidades son distintas; sí mantenemos el mismo orden de categorías."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport matplotlib.pyplot as plt\nr=datos.groupby(\"Producto\")[[\"Unidades\",\"Ingreso\"]].sum()\nfig,axes=plt.subplots(1,2,figsize=(10,4),layout=\"constrained\")\naxes[0].bar(r.index,r.Unidades,color=\"#216556\")\naxes[1].bar(r.index,r.Ingreso,color=\"#7155ba\")\naxes[0].set(title=\"Volumen por producto\",ylabel=\"Unidades\")\naxes[1].set(title=\"Ingreso por producto\",ylabel=\"Ingreso (CRC)\")\nplt.show()", "output": "Dos paneles comparan productos A, B y C con unidades claramente distintas.", "tip": "Compartir escala solo es útil cuando la magnitud y la unidad son comparables.", "image": "graficos/sesion_19_1.png"}, {"title": "Títulos, etiquetas y anotaciones útiles", "text": ["Un título puede expresar un hallazgo verificable, pero debe limitarse al conjunto observado. Usa anotaciones para señalar un punto que merece atención; no conviertas cada dato en una etiqueta.", "Las barras parten de cero para conservar la comparación de longitudes. Usa color con significado, contraste suficiente y etiquetas que permitan comprender el gráfico sin distinguir colores."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport matplotlib.pyplot as plt\nr=datos.groupby(\"Producto\").Ingreso.sum().sort_values()\nfig,ax=plt.subplots(figsize=(7,4),layout=\"constrained\")\nbarras=ax.barh(r.index,r.values,color=\"#216556\")\nax.bar_label(barras,fmt=\"%.0f\",padding=4)\nax.set(xlabel=\"Ingreso (CRC)\",title=\"Ingreso registrado por producto · datos sintéticos\")\nax.set_xlim(0,r.max()*1.2)\nax.spines[[\"top\",\"right\"]].set_visible(False)\nplt.show()", "output": "A: 1600; B: 2800; C: 3000 CRC. Los valores aparecen al final de las barras.", "tip": "No llames ganancia a un ingreso: el conjunto no incluye costos.", "image": "graficos/sesion_19_2.png"}, {"title": "Exportar para pantalla y documento", "text": ["PNG es una imagen de píxeles; SVG conserva formas vectoriales que escalan con nitidez. Elige formato según el destino, no por costumbre. dpi afecta principalmente la resolución de los elementos rasterizados.", "Guarda la figura antes de cerrar el entorno. bbox_inches=\"tight\" reduce recortes, pero igualmente revisa título, leyendas, ejes y tamaño real de lectura. Evita títulos diminutos para hacer caber más información."], "code": "import matplotlib.pyplot as plt\nfig,ax=plt.subplots(figsize=(7,4),layout=\"constrained\")\nax.plot([1,2,3],[10,15,12],marker=\"o\",color=\"#216556\")\nax.set(title=\"Unidades registradas en tres días\",xlabel=\"Día\",ylabel=\"Unidades\")\nfig.savefig(\"reporte_matplotlib.png\",dpi=150,bbox_inches=\"tight\")\nfig.savefig(\"reporte_matplotlib.svg\",bbox_inches=\"tight\")\nplt.show()", "output": "Se generan reporte_matplotlib.png y reporte_matplotlib.svg.", "tip": "Una imagen atractiva no sustituye la fuente, las unidades ni una interpretación correcta.", "image": "graficos/sesion_19_3.png"}], "tasks": [{"title": "Dos magnitudes, dos paneles", "prompt": "Usa los datos de práctica y representa unidades e ingreso en dos Axes.", "solution": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport matplotlib.pyplot as plt\nr=datos.groupby(\"Producto\")[[\"Unidades\",\"Ingreso\"]].sum()\nfig,ax=plt.subplots(1,2,figsize=(10,4),layout=\"constrained\")\nax[0].bar(r.index,r.Unidades);ax[0].set_ylabel(\"Unidades\")\nax[1].bar(r.index,r.Ingreso);ax[1].set_ylabel(\"Ingreso (CRC)\")\nplt.show()", "check": "Cada panel tiene su unidad y conserva el orden de productos.", "hint": "Usa subplots(1,2).", "explanation": "Cada panel tiene su unidad y conserva el orden de productos."}, {"title": "Exportación verificable", "prompt": "Crea barras A=20 y B=30 unidades y exporta PNG y SVG.", "solution": "import matplotlib.pyplot as plt\nfig,ax=plt.subplots(layout=\"constrained\")\nax.bar([\"A\",\"B\"],[20,30]);ax.set(title=\"Unidades por producto\",ylabel=\"Unidades\")\nfig.savefig(\"reto_barras.png\",dpi=150,bbox_inches=\"tight\")\nfig.savefig(\"reto_barras.svg\",bbox_inches=\"tight\")\nplt.show()", "check": "Ambos archivos representan los mismos valores y etiquetas.", "hint": "Usa fig.savefig dos veces.", "explanation": "Ambos archivos representan los mismos valores y etiquetas."}], "quiz": [{"question": "¿Qué representa Axes?", "options": ["Una región de trazado", "Una tabla", "Un archivo CSV"], "answer": 0, "explanation": "Figure puede contener uno o varios Axes."}, {"question": "¿Por qué evitar un eje compartido para unidades y CRC?", "options": ["Son magnitudes distintas", "Matplotlib no acepta números", "Siempre hay que usar porcentajes"], "answer": 0, "explanation": "La comparación debe respetar las unidades."}, {"question": "¿Qué formato conserva gráficos vectoriales?", "options": ["SVG", "CSV", "TXT"], "answer": 0, "explanation": "SVG describe formas; PNG almacena píxeles."}], "homework": {"title": "Laboratorio · Matplotlib aplicado", "context": "Diseña figuras compuestas, anota hallazgos y exporta gráficos legibles.", "steps": ["Crea un reporte con dos paneles usando ventas.csv.", "Ordena categorías, indica unidades y añade una anotación justificable.", "Exporta PNG y SVG y comprueba la legibilidad.", "Escribe un hallazgo numérico y una limitación."]}, "id": 19, "badge": 4, "phase": "Badge 4 · Visualización y narrativa de datos"}, {"title": "Seaborn: explora distribuciones y relaciones", "short": "Seaborn estadístico", "description": "Relaciona columnas con variables visuales y distingue observaciones de estimaciones.", "objectives": ["Usar hue y gráficos de distribución.", "Controlar agregaciones y barras de error.", "Combinar gráficos con Axes y facetas."], "lessons": [{"title": "Distribuciones: observa antes de resumir", "text": ["Seaborn trabaja naturalmente con tablas en formato largo. data indica el DataFrame y x, y, hue y col nombran variables. hue separa grupos mediante color; incluye leyenda y categorías comprensibles.", "Un histograma cuenta observaciones dentro de intervalos. Una caja resume mediana y cuartiles, pero puede ocultar el tamaño y la forma de una muestra pequeña. Superponer puntos permite mostrar las observaciones reales."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport seaborn as sns\nimport matplotlib.pyplot as plt\nsns.set_theme(style=\"whitegrid\")\nfig,ax=plt.subplots(1,2,figsize=(10,4),layout=\"constrained\")\nsns.histplot(data=datos,x=\"Unidades\",hue=\"Sucursal\",multiple=\"dodge\",binwidth=1,ax=ax[0])\nsns.boxplot(data=datos,x=\"Sucursal\",y=\"Unidades\",color=\"#c4ef88\",ax=ax[1])\nsns.stripplot(data=datos,x=\"Sucursal\",y=\"Unidades\",color=\"#182638\",jitter=False,ax=ax[1])\nax[0].set_title(\"Unidades por registro\");ax[1].set_title(\"Distribución por sucursal\")\nplt.show()", "output": "Se muestran 12 registros. La caja y los puntos permiten comparar ambas sucursales sin ocultar observaciones.", "tip": "Con pocos datos, una curva de densidad puede aparentar más evidencia de la disponible.", "image": "graficos/sesion_20_1.png"}, {"title": "barplot agrega; scatterplot muestra pares", "text": ["barplot calcula una estimación por categoría: de forma predeterminada, una media. No lo confundas con el total de una columna. Si quieres ingresos totales, agrupa de manera explícita o indica el estimador que corresponde.", "Las barras de error representan una definición de incertidumbre o dispersión, no decoración. En este ejemplo mostramos totales exactos del conjunto de práctica, por lo que desactivamos el intervalo con errorbar=None y lo explicamos."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport seaborn as sns\nimport matplotlib.pyplot as plt\nr=datos.groupby(\"Producto\",as_index=False).Ingreso.sum()\nfig,ax=plt.subplots(figsize=(7,4),layout=\"constrained\")\nsns.barplot(data=r,x=\"Producto\",y=\"Ingreso\",errorbar=None,color=\"#216556\",ax=ax)\nax.set(title=\"Ingreso total observado por producto\",ylabel=\"Ingreso (CRC)\")\nplt.show()", "output": "Los totales son 1600, 2800 y 3000 CRC; no son promedios por registro.", "tip": "Antes de interpretar cualquier barra, identifica qué se está agregando y qué representa su intervalo.", "image": "graficos/sesion_20_2.png"}, {"title": "Funciones por eje y funciones por figura", "text": ["scatterplot, histplot y boxplot aceptan ax para integrarse en una figura Matplotlib. relplot, displot y catplot administran su propia figura y permiten dividir en facetas.", "Usa facetas para comparar grupos con la misma escala. No añadas demasiadas categorías: el tamaño de cada panel debe seguir permitiendo leer datos, etiquetas y leyendas."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport seaborn as sns\nimport matplotlib.pyplot as plt\ng=sns.relplot(data=datos,x=\"Unidades\",y=\"Ingreso\",hue=\"Producto\",style=\"Producto\",col=\"Sucursal\",height=3.5,aspect=1)\ng.set_axis_labels(\"Unidades por registro\",\"Ingreso (CRC)\")\ng.set_titles(\"Sucursal: {col_name}\")\ng.figure.suptitle(\"Relación entre volumen e ingreso · práctica\",y=1.05)\nplt.show()", "output": "Una faceta por sucursal muestra cada venta como un punto. Producto se distingue por color y forma.", "tip": "La relación entre unidades e ingreso es parcialmente mecánica: Ingreso = Precio × Unidades; no prueba un efecto causal.", "image": "graficos/sesion_20_3.png"}], "tasks": [{"title": "Comparación visible", "prompt": "Compara unidades por sucursal usando boxplot y puntos.", "solution": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport seaborn as sns\nimport matplotlib.pyplot as plt\nfig,ax=plt.subplots()\nsns.boxplot(data=datos,x=\"Sucursal\",y=\"Unidades\",ax=ax)\nsns.stripplot(data=datos,x=\"Sucursal\",y=\"Unidades\",color=\"black\",jitter=False,ax=ax)\nplt.show()", "check": "Las 12 observaciones aparecen junto al resumen.", "hint": "Ambas funciones reciben el mismo ax.", "explanation": "Las 12 observaciones aparecen junto al resumen."}, {"title": "Controla el resumen", "prompt": "Grafica ingreso total por sucursal y desactiva intervalos que no corresponden.", "solution": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport seaborn as sns\nimport matplotlib.pyplot as plt\nr=datos.groupby(\"Sucursal\",as_index=False).Ingreso.sum()\nfig,ax=plt.subplots()\nsns.barplot(data=r,x=\"Sucursal\",y=\"Ingreso\",errorbar=None,ax=ax)\nax.set_ylabel(\"Ingreso (CRC)\")\nplt.show()", "check": "Centro suma 3250 CRC; Norte suma 4150 CRC.", "hint": "Agrupa antes de graficar.", "explanation": "Centro suma 3250 CRC; Norte suma 4150 CRC."}], "quiz": [{"question": "¿Qué calcula barplot por defecto?", "options": ["Media", "Suma siempre", "Ninguna agregación"], "answer": 0, "explanation": "Controla estimator o agrega previamente según tu pregunta."}, {"question": "¿Qué función puede recibir ax?", "options": ["scatterplot", "relplot", "displot"], "answer": 0, "explanation": "scatterplot opera a nivel de eje; relplot y displot administran figuras."}, {"question": "¿Qué aportan puntos junto a una caja?", "options": ["Observaciones individuales", "Prueba de causalidad", "Más registros reales"], "answer": 0, "explanation": "Ayudan a ver el tamaño y los valores de la muestra."}], "homework": {"title": "Laboratorio · Seaborn estadístico", "context": "Relaciona columnas con variables visuales y distingue observaciones de estimaciones.", "steps": ["Usa los datos de práctica o ventas_proyecto.csv ya limpio.", "Compara dos distribuciones con cajas y puntos.", "Crea un gráfico con facetas y explica hue, col y escalas.", "Describe si cada gráfico muestra datos individuales, conteos o estimaciones."]}, "id": 20, "badge": 4, "phase": "Badge 4 · Visualización y narrativa de datos"}, {"title": "Plotly: deja que el lector explore", "short": "Plotly interactivo", "description": "Crea gráficos interactivos con información al pasar el cursor, leyendas y exportación HTML.", "objectives": ["Construir figuras con Plotly Express.", "Personalizar trazas y layout.", "Compartir un HTML con los datos adecuados."], "lessons": [{"title": "Plotly Express: de tabla a figura", "text": ["Plotly Express devuelve una Figure que puede personalizarse después. Los gráficos permiten explorar puntos con el cursor y ocultar series desde la leyenda. En px.bar los valores no se resumen automáticamente como en un barplot estadístico: prepara los totales antes.", "hover_data controla qué columnas aparecen al explorar. Un dato oculto en el gráfico puede seguir presente en el archivo exportado; comparte únicamente los datos que corresponde distribuir."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport plotly.express as px\nr=datos.groupby([\"Sucursal\",\"Producto\"],as_index=False).Ingreso.sum()\nfig=px.bar(r,x=\"Producto\",y=\"Ingreso\",color=\"Sucursal\",barmode=\"group\",labels={\"Ingreso\":\"Ingreso (CRC)\"},title=\"Ingreso por producto y sucursal\")\nfig.update_layout(template=\"plotly_white\",legend_title_text=\"Sucursal\")\nfig.show()", "output": "Barras agrupadas para Centro y Norte. La leyenda permite ocultar series y el cursor muestra sus valores.", "tip": "La interacción debe ayudar a responder una pregunta; no reemplaza título, unidades ni contexto.", "interactive": "graficos/interactivo_21_1.html"}, {"title": "Trazas, layout y exploración temporal", "text": ["Una figura separa datos y apariencia: las trazas contienen series; layout define títulos, ejes, leyendas y otras opciones. update_traces modifica propiedades de las series y update_layout modifica la composición.", "Ordena por fecha antes de unir puntos con líneas. Un selector de rango permite explorar un intervalo sin cambiar los datos originales. Aclara que un cambio de escala o rango altera lo visible, no los valores almacenados."], "code": "import pandas as pd\nimport plotly.express as px\ndf=pd.DataFrame({\"Fecha\":pd.date_range(\"2026-01-01\",periods=8),\"Ingreso\":[100,120,90,150,160,140,180,170]})\nfig=px.line(df.sort_values(\"Fecha\"),x=\"Fecha\",y=\"Ingreso\",markers=True,title=\"Ingresos diarios · datos sintéticos\",labels={\"Ingreso\":\"Ingreso (CRC)\"})\nfig.update_traces(line_color=\"#216556\",hovertemplate=\"%{x|%d/%m/%Y}<br>CRC %{y:.0f}<extra></extra>\")\nfig.update_xaxes(rangeslider_visible=True)\nfig.update_layout(template=\"plotly_white\")\nfig.show()", "output": "Una serie de ocho días con selector de rango e información de fecha y monto al pasar el cursor.", "tip": "Un zoom no es un filtro analítico aplicado al conjunto; distingue exploración visual y transformación de datos.", "interactive": "graficos/interactivo_21_2.html"}, {"title": "Exporta un HTML que se pueda abrir", "text": ["write_html permite compartir un gráfico sin un servidor Python. include_plotlyjs=True incluye la biblioteca dentro del HTML: el archivo es más grande, pero puede abrirse sin conexión. Con \"cdn\", el lector necesita internet para cargarla.", "Para PNG o SVG, Plotly requiere herramientas adicionales de exportación como Kaleido y un navegador compatible según la versión. En este curso usamos HTML para evitar ese requisito; abre el resultado y comprueba la interacción antes de entregarlo."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport plotly.express as px\nfig=px.scatter(datos,x=\"Unidades\",y=\"Ingreso\",color=\"Sucursal\",symbol=\"Producto\",hover_data=[\"Producto\"],labels={\"Ingreso\":\"Ingreso (CRC)\"},title=\"Ventas de práctica\")\nfig.update_layout(template=\"plotly_white\")\nfig.write_html(\"ventas_interactivas.html\",include_plotlyjs=True,full_html=True,auto_open=False)\nprint(\"Archivo creado: ventas_interactivas.html\")\nfig.show()", "output": "Se crea ventas_interactivas.html con el gráfico y su biblioteca incluidos.", "tip": "HTML interactivo no equivale a un panel con base de datos ni a actualizaciones en tiempo real.", "interactive": "graficos/interactivo_21_3.html"}], "tasks": [{"title": "Barras que se exploran", "prompt": "Agrupa ingreso por producto y genera barras con Plotly.", "solution": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport plotly.express as px\nr=datos.groupby(\"Producto\",as_index=False).Ingreso.sum()\nfig=px.bar(r,x=\"Producto\",y=\"Ingreso\",labels={\"Ingreso\":\"Ingreso (CRC)\"},title=\"Ingreso total por producto\")\nfig.show()", "check": "Tres barras con ingresos 1600, 2800 y 3000.", "hint": "Agrupa antes de llamar px.bar.", "explanation": "Tres barras con ingresos 1600, 2800 y 3000."}, {"title": "Una entrega portátil", "prompt": "Exporta una dispersión a HTML autónomo con datos sintéticos.", "solution": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport plotly.express as px\nfig=px.scatter(datos,x=\"Unidades\",y=\"Ingreso\",color=\"Sucursal\")\nfig.write_html(\"reto_plotly.html\",include_plotlyjs=True,auto_open=False)\nfig.show()", "check": "reto_plotly.html incluye la biblioteca y no necesita CDN.", "hint": "Usa include_plotlyjs=True.", "explanation": "reto_plotly.html incluye la biblioteca y no necesita CDN."}], "quiz": [{"question": "¿px.bar agrega automáticamente una media por categoría?", "options": ["Sí", "No", "Solo si hay colores"], "answer": 1, "explanation": "Prepara el resumen o comprende las trazas de los registros que suministras."}, {"question": "¿Qué cambia update_layout?", "options": ["Composición, ejes y títulos", "Los CSV originales", "La media de los datos"], "answer": 0, "explanation": "Layout controla la presentación de la figura."}, {"question": "¿Qué permite include_plotlyjs=True?", "options": ["HTML autónomo con biblioteca incluida", "Eliminar todos los datos", "Crear una base de datos"], "answer": 0, "explanation": "Aumenta el tamaño, pero evita depender de una CDN."}], "homework": {"title": "Laboratorio · Plotly interactivo", "context": "Crea gráficos interactivos con información al pasar el cursor, leyendas y exportación HTML.", "steps": ["Crea barras por categoría y una serie temporal con selector de rango.", "Personaliza títulos, unidades y datos del cursor.", "Exporta al menos una figura a HTML autónomo.", "Explica qué interacciones ayudan a responder tu pregunta y qué datos contiene el archivo."]}, "id": 21, "badge": 4, "phase": "Badge 4 · Visualización y narrativa de datos"}, {"title": "Convierte gráficos en una explicación", "short": "Narrativa visual", "description": "Elige herramientas y combina evidencia, accesibilidad y límites en una entrega coherente.", "objectives": ["Elegir gráficos según la pregunta.", "Detectar escalas o agregaciones engañosas.", "Construir una narrativa con gráficos estáticos e interactivos."], "lessons": [{"title": "Pregunta, audiencia y gráfico", "text": ["Antes de elegir una biblioteca, define qué debe comprender el lector. Comparar categorías, describir una distribución y explorar una relación requieren representaciones distintas. Matplotlib ofrece control fino; Seaborn facilita gráficos estadísticos; Plotly permite exploración interactiva.", "Un título con conclusión debe sostenerse en datos y delimitar el contexto. Evita afirmar una tendencia general a partir de un conjunto pequeño o sintético."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nimport matplotlib.pyplot as plt\nr=datos.groupby(\"Sucursal\").Ingreso.sum()\nfig,ax=plt.subplots(figsize=(7,4),layout=\"constrained\")\nbars=ax.bar(r.index,r.values,color=[\"#7155ba\",\"#216556\"])\nax.bar_label(bars,fmt=\"%.0f\",padding=3)\nax.set(title=\"Norte registra más ingreso en estas 12 ventas\",ylabel=\"Ingreso (CRC)\",ylim=(0,5000))\nplt.show()", "output": "Norte: 4150 CRC; Centro: 3250 CRC. El título limita el hallazgo a las 12 ventas.", "tip": "Mayor ingreso no demuestra mayor rentabilidad ni mejor desempeño causal.", "image": "graficos/sesion_22_1.png"}, {"title": "Accesibilidad y comparaciones honestas", "text": ["Usa etiquetas directas, contraste legible y símbolos además de color. Para barras, un origen distinto de cero puede exagerar diferencias. En líneas puede ser razonable acotar el eje, pero debes mostrar la escala y justificarla.", "Mantén unidades y escalas comparables cuando contrastas grupos. Añade un resumen textual de los hallazgos para personas que no puedan interactuar con el gráfico."], "code": "import matplotlib.pyplot as plt\nfig,ax=plt.subplots(figsize=(7,4),layout=\"constrained\")\nax.plot([1,2,3],[10,12,14],marker=\"o\",linestyle=\"-\",label=\"Centro\")\nax.plot([1,2,3],[11,13,15],marker=\"s\",linestyle=\"--\",label=\"Norte\")\nax.set(title=\"Unidades por día · ejemplo sintético\",xlabel=\"Día\",ylabel=\"Unidades\")\nax.legend(title=\"Sucursal\")\nplt.show()", "output": "Ambas series se distinguen por etiqueta, marcador y estilo de línea, incluso sin reconocer sus colores.", "tip": "No uses el color como único canal para comunicar una diferencia esencial.", "image": "graficos/sesion_22_2.png"}, {"title": "Una historia verificable", "text": ["Una entrega puede seguir tres pasos: qué se observó, qué evidencia lo respalda y qué límites condicionan la interpretación. Incluye fuente, período, unidades y reglas de limpieza.", "No agregues gráficos que repitan la misma información sin aportar una comparación útil. Selecciona tres vistas complementarias y acompaña cada una con una conclusión breve. Los archivos deben poder abrirse fuera de tu sesión."], "code": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nresumen=datos.groupby(\"Sucursal\").Ingreso.sum()\ntotal=resumen.sum()\nporcentaje=100*resumen[\"Norte\"]/total\nprint(f\"Norte aporta {porcentaje:.1f}% del ingreso registrado.\")\nprint(\"Fuente: 12 registros sintéticos; moneda CRC.\")\nprint(\"Límite: no hay costos ni una muestra representativa del mercado.\")", "output": "Norte aporta 56.1 % de 7400 CRC registrados. Se explicitan fuente y límites.", "tip": "Una recomendación debe ser proporcional a lo que la evidencia permite sostener."}], "tasks": [{"title": "Redacta con evidencia", "prompt": "Calcula qué proporción aporta Norte y escribe una conclusión delimitada.", "solution": "import pandas as pd\ndatos = pd.DataFrame({\n    \"Sucursal\": [\"Centro\"]*6 + [\"Norte\"]*6,\n    \"Producto\": [\"A\", \"B\", \"C\"]*4,\n    \"Unidades\": [2, 4, 3, 5, 2, 6, 3, 5, 4, 6, 3, 7],\n    \"Precio\": [100, 200, 150]*4\n})\ndatos[\"Ingreso\"] = datos[\"Unidades\"] * datos[\"Precio\"]\nr=datos.groupby(\"Sucursal\").Ingreso.sum()\nprint(f\"Norte aporta {100*r[\"Norte\"]/r.sum():.1f}% en estos registros sintéticos.\")", "check": "56.1 %; el alcance queda explícito.", "hint": "Divide el subtotal entre el total observado.", "explanation": "56.1 %; el alcance queda explícito."}, {"title": "Más que un color", "prompt": "Representa dos series con marcadores y líneas distintas.", "solution": "import matplotlib.pyplot as plt\nfig,ax=plt.subplots()\nax.plot([1,2],[10,12],marker=\"o\",label=\"A\")\nax.plot([1,2],[11,13],marker=\"s\",linestyle=\"--\",label=\"B\")\nax.set(xlabel=\"Día\",ylabel=\"Unidades\",title=\"Dos series de práctica\")\nax.legend()\nplt.show()", "check": "Las series se distinguen mediante formas, líneas y leyenda.", "hint": "Combina marker y linestyle.", "explanation": "Las series se distinguen mediante formas, líneas y leyenda."}], "quiz": [{"question": "¿Qué debe definir la elección del gráfico?", "options": ["La pregunta y el tipo de dato", "La biblioteca de moda", "El número de colores"], "answer": 0, "explanation": "La representación debe facilitar la comparación que necesitas."}, {"question": "¿Por qué acompañar un gráfico con texto?", "options": ["Para comunicar hallazgo y límites de forma accesible", "Para ocultar los ejes", "Para probar causalidad"], "answer": 0, "explanation": "El texto contextualiza la evidencia y ayuda a distintas formas de acceso."}, {"question": "¿Qué convierte una entrega en reproducible?", "options": ["Datos, código y decisiones suficientes para repetirla", "Solo un PNG", "Un título llamativo"], "answer": 0, "explanation": "La figura final necesita un proceso verificable."}], "homework": {"title": "Laboratorio · Narrativa visual", "context": "Elige herramientas y combina evidencia, accesibilidad y límites en una entrega coherente.", "steps": ["Elige una pregunta y genera un gráfico con cada biblioteca.", "Incluye un resumen textual accesible de cada figura.", "Entrega notebook, PNG o SVG y HTML autónomo.", "Escribe un informe de máximo 300 palabras con dos hallazgos y dos limitaciones."]}, "id": 22, "badge": 4, "phase": "Badge 4 · Visualización y narrativa de datos"}];
